  values: T[],
): ReadableStream<T> {
  return new ReadableStream({
    start(controller) {
      try {
        for (const value of values) {
          controller.enqueue(value);
        }
      } finally {
        controller.close();
      }
    },
  });
}
","export async function convertAsyncIterableToArray<T>(
  iterable: AsyncIterable<T>,
): Promise<T[]> {
