export function isIterable<IteratorType>(
  fn: any,
): fn is
  | Iterable<IteratorType, IteratorType, IteratorType>
  | AsyncIterable<IteratorType, IteratorType, IteratorType> {
  if (!fn) {
    return false
  }

  return (
