","import chalk from "chalk";
import ora from "ora";
import {
  ExperimentsApiService,
  type ExperimentRunSummaryEntry,
} from "@/client-sdk/services/experiments/experiments-api.service";
import { checkApiKey } from "../../utils/apiKey";
import { failSpinner } from "../../utils/spinnerError";
import { formatTable } from "../../utils/formatting";

export interface ListRunsOptions {
  experiment?: string;
  format?: string;
  limit?: string;
}

const DEFAULT_LIMIT = 50;
const MAX_PAGE_SIZE = 200;

const formatTimestamp = (epochMs: number | null | undefined): string => {
  if (!epochMs || !Number.isFinite(epochMs)) return chalk.gray("—");
  return new Date(epochMs).toLocaleString();
};

const summarizePassRate = (
  evaluations: ExperimentRunSummaryEntry["summary"]["evaluations"],
): string => {
  const entries = Object.values(evaluations ?? {});
  if (entries.length === 0) return chalk.gray("—");
  const passEntries = entries.filter(
    (e) => typeof e.averagePassed === "number",
  );
  if (passEntries.length === 0) {
    const scoreEntries = entries.filter(
      (e) => typeof e.averageScore === "number",
    );
    if (scoreEntries.length === 0) return chalk.gray("—");
    const avg =
      scoreEntries.reduce((sum, e) => sum + (e.averageScore ?? 0), 0) /
      scoreEntries.length;
    return `${avg.toFixed(2)} avg`;
  }
  const avg =
    passEntries.reduce((sum, e) => sum + (e.averagePassed ?? 0), 0) /
    passEntries.length;
  return `${(avg * 100).toFixed(0)}% pass`;
};

const runStatus = (run: ExperimentRunSummaryEntry): string => {
  if (run.timestamps.stoppedAt) return chalk.gray("stopped");
  if (run.timestamps.finishedAt) return chalk.green("completed");
  return chalk.yellow("running");
};

export const experimentListRunsCommand = async (
  options: ListRunsOptions = {},
): Promise<void> => {
  checkApiKey();

  const experimentSlug = options.experiment?.trim();
  if (!experimentSlug) {
    console.error(
      chalk.red(
        "Error: --experiment <slug> is required. List experiments first with `langwatch experiment list`.",
      ),
    );
    process.exit(1);
  }

  const format = options.format === "json" ? "json" : "table";
  const limit = (() => {
    const parsed = options.limit ? parseInt(options.limit, 10) : DEFAULT_LIMIT;
    if (!Number.isFinite(parsed) || parsed <= 0) return DEFAULT_LIMIT;
    return Math.min(parsed, MAX_PAGE_SIZE);
  })();

  const service = new ExperimentsApiService();
  const spinner = ora(
    `Fetching runs for "${experimentSlug}"...`,
  ).start();

  try {
    const result = await service.listRuns({
      experimentSlug,
      pageSize: limit,
    });

    spinner.succeed(
      `Found ${result.pagination.totalHits} run${result.pagination.totalHits === 1 ? "" : "s"} for ${chalk.cyan(experimentSlug)}`,
    );

    if (format === "json") {
      console.log(JSON.stringify(result, null, 2));
      return;
    }

    if (result.runs.length === 0) {
      console.log();
      console.log(chalk.gray("No runs found for this experiment yet."));
      return;
    }

    console.log();

    const tableData = result.runs.map((run) => ({
      "Run ID": run.runId,
      Status: runStatus(run),
      Progress:
        typeof run.progress === "number" && typeof run.total === "number"
          ? `${run.progress}/${run.total}`
          : chalk.gray("—"),
      Started: formatTimestamp(run.timestamps.createdAt),
      Finished: formatTimestamp(run.timestamps.finishedAt),
      Result: summarizePassRate(run.summary?.evaluations ?? {}),
    }));

    formatTable({
      data: tableData,
      headers: ["Run ID", "Status", "Progress", "Started", "Finished", "Result"],
      colorMap: {
        "Run ID": chalk.cyan,
      },
    });

    if (result.pagination.hasMore) {
      console.log();
      console.log(
        chalk.gray(
          `Showing ${result.runs.length} of ${result.pagination.totalHits}. Increase with --limit or use --format json for full data.`,
        ),
      );
    }

    console.log();
    console.log(
      chalk.gray(
        `Use ${chalk.cyan("langwatch experiment status <runId>")} or ${chalk.cyan("langwatch experiment results <runId>")} to drill into a run.`,
      ),
    );
  } catch (error) {
    failSpinner({ spinner, error, action: "list experiment runs" });
    process.exit(1);
  }
};
","import chalk from "chalk";
import ora from "ora";
import {
  ExperimentsApiService,
  type ExperimentRunResultsResponse,
  type ExperimentRunDatasetEntry,
  type ExperimentRunEvaluation,
} from "@/client-sdk/services/experiments/experiments-api.service";
import {
  deriveRunStatus,
  isTerminalStatus,
} from "@/client-sdk/services/experiments/run-status";
import { checkApiKey } from "../../utils/apiKey";
import { failSpinner } from "../../utils/spinnerError";
import { formatTable } from "../../utils/formatting";
import { resolveRunId } from "./resolve-run";

export type ExperimentResultsFilter = "failed" | "all";
export type ExperimentResultsFormat = "table" | "json";

export interface ExperimentResultsOptions {
  filter?: string;
  evaluator?: string;
  format?: string;
  limit?: string;
  runId?: string;
}

const DEFAULT_LIMIT = 20;

const rowKey = (index: number, targetId?: string | null): string =>
  `${index}:${targetId ?? ""}`;

const summarizeEntry = (entry: Record<string, unknown>): string => {
  // Pick something meaningful: input, question, query, prompt, or first string field
  const candidates = ["input", "question", "query", "prompt", "user"];
  for (const key of candidates) {
    const value = entry[key];
    if (typeof value === "string" && value.length > 0) {
      return value.length > 60 ? `${value.slice(0, 57)}...` : value;
    }
  }
  const firstString = Object.entries(entry).find(
    ([, v]) => typeof v === "string" && v.length > 0,
  );
  if (firstString) {
    const v = firstString[1] as string;
    return v.length > 60 ? `${v.slice(0, 57)}...` : v;
  }
  return chalk.gray("—");
};

const isFailedEvaluation = (evaluation: ExperimentRunEvaluation): boolean => {
  if (evaluation.status === "error") return true;
  if (evaluation.passed === false) return true;
  return false;
};

const isFailedRow = ({
  entry,
  evaluations,
}: {
  entry: ExperimentRunDatasetEntry;
  evaluations: ExperimentRunEvaluation[];
}): boolean => {
  if (entry.error) return true;
  return evaluations.some((e) => isFailedEvaluation(e));
};

export const experimentResultsCommand = async ({
  experimentSlug,
  options = {},
}: {
  experimentSlug: string;
  options?: ExperimentResultsOptions;
}): Promise<void> => {
  checkApiKey();

  const filter: ExperimentResultsFilter =
    options.filter === "failed" ? "failed" : "all";
  const format: ExperimentResultsFormat =
    options.format === "json" ? "json" : "table";
  const limit = (() => {
    const parsed = options.limit ? parseInt(options.limit, 10) : DEFAULT_LIMIT;
    return Number.isFinite(parsed) && parsed > 0 ? parsed : DEFAULT_LIMIT;
  })();
  const evaluatorFilter = options.evaluator?.trim();

  const service = new ExperimentsApiService();
  const spinner = ora(`Fetching results for "${experimentSlug}"...`).start();

  try {
    const runId = await resolveRunId({
      service,
      experimentSlug,
      runId: options.runId,
    });
    const results: ExperimentRunResultsResponse = await service.getRunResults({
      runId,
      experimentSlug,
    });
    const runStatus = deriveRunStatus(results.timestamps);
    spinner.succeed(
      `Loaded results for ${chalk.cyan(runId)} (${results.dataset.length} rows, ${results.evaluations.length} evaluations)`,
    );

    if (!isTerminalStatus(runStatus) && format !== "json") {
      console.log(
        chalk.yellow(
          runStatus === "interrupted"
            ? `Run status: interrupted. These are partial results (the run never sent a finished/stopped marker and has had no recent updates).`
            : `Run status: running. These are partial results; more rows may appear later.`,
        ),
      );
    }

    // Group evaluations by target-scoped row key.
    const evaluationsByRow = new Map<string, ExperimentRunEvaluation[]>();
    for (const evaluation of results.evaluations) {
      if (evaluatorFilter && evaluation.evaluator !== evaluatorFilter) continue;
      const key = rowKey(evaluation.index, evaluation.targetId);
      const list = evaluationsByRow.get(key) ?? [];
      list.push(evaluation);
      evaluationsByRow.set(key, list);
    }

    // Determine evaluator columns to show
    const evaluatorNames = evaluatorFilter
      ? [evaluatorFilter]
      : Array.from(
          new Set(results.evaluations.map((e) => e.evaluator)),
        ).slice(0, 3); // cap visible columns to keep table readable

    let rows = results.dataset.map((entry) => ({
      entry,
      evaluations: evaluationsByRow.get(rowKey(entry.index, entry.targetId)) ?? [],
    }));

    if (filter === "failed") {
      rows = rows.filter((r) =>
        isFailedRow({ entry: r.entry, evaluations: r.evaluations }),
      );
    }

    const totalMatching = rows.length;
    const truncated = rows.length > limit;
    rows = rows.slice(0, limit);

    if (format === "json") {
      console.log(
        JSON.stringify(
          {
            ...results,
            dataset: rows.map((row) => row.entry),
            evaluations: rows.flatMap((row) => row.evaluations),
            meta: {
              totalMatching,
              truncated,
              limit,
              filter,
              evaluator: evaluatorFilter ?? null,
            },
          },
          null,
          2,
        ),
      );
      return;
    }

    if (rows.length === 0) {
      if (filter === "failed") {
        console.log(chalk.gray("No rows matched the filter."));
      } else if (runStatus === "running") {
        console.log(
          chalk.gray(
            "No rows recorded yet. The run is still in progress; run this again shortly.",
          ),
        );
      } else if (runStatus === "interrupted") {
        console.log(
          chalk.gray("No rows were recorded before the run was interrupted."),
        );
      } else {
        console.log(chalk.gray("No rows recorded for this run."));
      }
      return;
    }

    const headers = ["#", "Target", ...evaluatorNames, "Status"];
    const tableData = rows.map(({ entry, evaluations }) => {
      const evaluatorCols: Record<string, string> = {};
      for (const name of evaluatorNames) {
        const e = evaluations.find((x) => x.evaluator === name);
        if (!e) {
          evaluatorCols[name] = chalk.gray("—");
        } else if (e.status === "error") {
          evaluatorCols[name] = chalk.red("error");
        } else if (typeof e.score === "number") {
          const passedSuffix =
            e.passed === false
              ? chalk.red(" ✗")
              : e.passed === true
                ? chalk.green(" ✓")
                : "";
          evaluatorCols[name] = `${e.score.toFixed(2)}${passedSuffix}`;
        } else if (e.label) {
          evaluatorCols[name] = e.label;
        } else if (typeof e.passed === "boolean") {
          evaluatorCols[name] = e.passed
            ? chalk.green("pass")
            : chalk.red("fail");
        } else {
          evaluatorCols[name] = chalk.gray("—");
        }
      }
      const status = entry.error
        ? chalk.red(
            entry.error.length > 40
              ? `${entry.error.slice(0, 37)}...`
              : entry.error,
          )
        : evaluations.some(isFailedEvaluation)
          ? chalk.red("failed")
          : chalk.green("ok");

      return {
        "#": String(entry.index),
        Target: summarizeEntry(entry.entry),
        ...evaluatorCols,
        Status: status,
      };
    });

    formatTable({ data: tableData, headers });

    if (truncated) {
      console.log();
      console.log(
        chalk.gray(
          `Showing ${rows.length} of ${totalMatching} rows. Use --limit <n> or --format json for the full payload.`,
        ),
      );
    }
  } catch (error) {
    failSpinner({ spinner, error, action: "fetch experiment results" });
    process.exit(1);
  }
};
