 * exec wrapper helper for `langwatch claude` / `codex` / `cursor` /
 * `gemini`. Loads the persisted device-flow config, optionally
 * pre-checks the budget (Screen-8 box + exit 2 if exceeded),
 * computes the right env-var pair for the tool, and spawns the
 * underlying binary inheriting stdio so the user keeps their
 * familiar UX.
 *
 * On Unix we use spawn() with stdio:'inherit'; signals (Ctrl-C,
 * SIGTERM) propagate via the child process group. We do NOT use
 * execve replacement - Node's child_process never replaces the
 * current process, but this is functionally equivalent for the
 * end-user (same exit code, same terminal handling) and works on
 * Windows where execve doesn't exist.
 */

import { spawn } from "node:child_process";
import type { GovernanceConfig } from "./config";
import { loadConfig, saveConfig, isLoggedIn } from "./config";
import { lwTag } from "./brand";
import { checkBudget, renderBudgetExceeded } from "./budget";
import { getCliBootstrap, GovernanceCliError } from "./cli-api";
import { runDeviceFlowLogin } from "./login-flow";
import { resolvePlatformToolPolicy } from "./platform-tool-policy";
import { maybeOfferIngestionShellRcPersist } from "./shell-rc";
import { resolveWrapperMode } from "./wrapper-mode";
import { createCodexIOStreamer } from "./codex-rollout-otlp";
import { parseToolModeFlag, resolveWrapperPath } from "./wrapper-path-choice";

/**
 * How often the wrapper polls codex's append-only rollout while the session
 * runs, streaming each completed turn's I/O instead of one burst on exit.
 */
const CODEX_IO_POLL_MS = 2_500;

export interface ToolEnv {
  /** Env-var name → value pairs to inject into the child process. */
  vars: Record<string, string>;
  /**
   * Env-var names to STRIP from the inherited parent environment
   * before spawning the tool. Used to scrub legacy credentials the
   * user has exported in their shell (e.g. ANTHROPIC_API_KEY set
   * from a previous direct-Anthropic workflow) that would otherwise
   * race with the gateway-routed auth (ANTHROPIC_AUTH_TOKEN) we
   * inject - claude-code 2.x detects both and warns
   * "auth may not work as expected", so we have to actively unset
   * the conflicting twin rather than just pile on top of it.
   * Unset BEFORE the merge so a tool that intentionally sets both
   * (opencode for provider auto-detect) still wins.
   */
  clears?: string[];
}

/**
 * Mirror of the Go CLI's env-injection map. The wrapped tools
 * read these standard env vars (Anthropic, OpenAI, Google) and
 * route through the gateway with the user's personal VK as bearer.
 *
 * Gateway-only on purpose: when the VK is on the API path the
 * gateway already captures every request + response server-side
 * (full I/O, exact cost). Injecting OTEL_* on top would make the
 * wrapped tool emit its own telemetry for the SAME calls = double
 * trace + double cost in /messages. The OTLP ingest path is for
 * users who can't go through the gateway at all (Claude Max
 * subscription, no swappable API key); they paste the OTEL env
 * block from the /me drawer manually. See
 * docs/ai-governance/track-your-claude-code-usage.mdx (Path A vs
 * Path B).
 */
export function envForTool(cfg: GovernanceConfig, tool: string): ToolEnv {
  const gw = cfg.gateway_url.replace(/\/+$/, "");
  const auth = cfg.default_personal_vk?.secret;
  if (!auth) return { vars: {} };
  switch (tool) {
    case "claude":
      // claude-code (2.1.x) appends `/v1/messages` to ANTHROPIC_BASE_URL itself.
      // Clear the legacy ANTHROPIC_API_KEY twin: claude-code warns
      // "Both ANTHROPIC_AUTH_TOKEN and ANTHROPIC_API_KEY set, auth may
      // not work as expected" when both are present (the gateway route
      // uses AUTH_TOKEN; API_KEY is left over from pre-langwatch direct
      // SDK usage). Stripping it leaves only the gateway-routed creds
      // on the child env.
      return {
        vars: {
          ANTHROPIC_BASE_URL: gw,
          ANTHROPIC_AUTH_TOKEN: auth,
        },
        clears: ["ANTHROPIC_API_KEY"],
      };
    case "codex":
      // codex 0.134 appends `/v1/chat/completions` itself.
      return {
        vars: {
          OPENAI_BASE_URL: gw,
          OPENAI_API_KEY: auth,
        },
      };
    case "cursor":
      // Same warning surface as claude: Anthropic SDKs nested in
      // cursor's runtime will read ANTHROPIC_API_KEY in preference to
      // ANTHROPIC_AUTH_TOKEN if both are set, bypassing the gateway.
      // Scrub the legacy key.
      return {
        vars: {
          OPENAI_BASE_URL: gw,
          OPENAI_API_KEY: auth,
          ANTHROPIC_BASE_URL: gw,
          ANTHROPIC_AUTH_TOKEN: auth,
        },
        clears: ["ANTHROPIC_API_KEY"],
      };
    case "gemini":
      // gemini-cli 0.46-preview honours `GOOGLE_GEMINI_BASE_URL`
      // (verified empirically in the bundled binary). It POSTs to
      // `{BASE}/v1beta/models/{model}:generateContent`, prepending
      // the `/v1beta/` itself. The base must therefore be the bare
      // gateway URL without the API version suffix; an earlier guess
      // of `${gw}/v1beta` doubled the prefix to `/v1beta/v1beta/` and
      // the gateway 404'd the routing call, surfacing as
      // "Unexpected end of JSON input" on the cli side.
      // `GOOGLE_GENAI_API_BASE` is NOT read by gemini-cli (separate
      // guess that silently no-op'd in earlier wrapper revisions).
      return {
        vars: {
          GOOGLE_GEMINI_BASE_URL: gw,
          GEMINI_API_KEY: auth,
          GOOGLE_API_KEY: auth,
        },
      };
    case "opencode":
      // opencode 1.x is multi-provider; under the hood it uses the
      // Vercel AI SDK, which appends `/messages` and `/chat/completions`
      // to the configured base URL WITHOUT prepending `/v1`. So opencode
      // needs the base to ALREADY include `/v1`, unlike claude-code +
      // codex which append it themselves. Verified via `--log-level
      // DEBUG` - opencode hit `${ANTHROPIC_BASE_URL}/messages` and
      // got a gateway 404 because the gateway exposes `/v1/messages`.
      //
      // Also: opencode's provider auto-detection at init time gates on
      // ANTHROPIC_API_KEY (NOT ANTHROPIC_AUTH_TOKEN, which claude-code
      // uses). Without it, opencode logs `providerID=openai found` /
      // `providerID=opencode found` but NOT anthropic, then fails any
      // `--model anthropic/...` invocation with ProviderModelNotFoundError.
      // Set both so anthropic is detected AND the gateway gets the VK on
      // the wire (the AI SDK forwards x-api-key from ANTHROPIC_API_KEY).
      return {
        vars: {
          OPENAI_BASE_URL: `${gw}/v1`,
          OPENAI_API_KEY: auth,
          ANTHROPIC_BASE_URL: `${gw}/v1`,
          ANTHROPIC_AUTH_TOKEN: auth,
          ANTHROPIC_API_KEY: auth,
        },
      };
    default:
      return { vars: {} };
  }
}

/**
 * Provider families the tool needs upstream. Used by `preflightWrapper`
 * to verify the org has at least one matching provider configured -
 * otherwise the gateway can authenticate the VK but has nothing to
 * route the request to, surfacing as a confusing tool-side error.
 *
 * Multi-provider tools (cursor, opencode) match any listed family.
 */
const TOOL_PROVIDER_FAMILIES: Record<string, string[]> = {
  claude: ["anthropic"],
  codex: ["openai"],
  cursor: ["anthropic", "openai"],
  gemini: ["google", "gemini"],
  opencode: ["anthropic", "openai"],
};

export interface PreflightResult {
  ok: boolean;
  /** Human-readable, action-oriented message rendered to stderr on failure. */
  message?: string;
  /**
   * Set on a failure a later retry might clear on its own - the gateway data
   * plane is momentarily unreachable. When absent/false the gateway path is
   * structurally unusable for this account/org (no virtual key, no provider
   * configured), so a remembered gateway choice is worth forgetting to re-offer
   * direct OTLP next time.
   */
  retryable?: boolean;
}

/**
 * Whether to forget a remembered gateway path choice after a failed gateway
 * preflight. True only when the user had pinned gateway AND the failure is
 * structural (no virtual key / no provider) rather than a retryable
 * gateway-down, so the next run re-prompts and can offer direct OTLP instead
 * of dead-ending on the same pinned choice every time.
 */
export function shouldForgetGatewayPin(args: {
  pinnedMode: string | undefined;
  retryable: boolean | undefined;
}): boolean {
  return args.pinnedMode === "gateway" && args.retryable !== true;
}

export interface PreflightOptions {
  fetchImpl?: typeof fetch;
  bootstrapImpl?: typeof getCliBootstrap;
  /** Per-probe timeout, ms. Default 3000. */
  timeoutMs?: number;
}

/**
 * Render the "who to talk to" footer attached to every preflight
 * failure message. Single source of truth so the admin-mailto format
 * stays consistent across the three failure shapes. Bootstrap is the
 * source of `adminEmail`; on legacy servers or unreachable control
 * planes it'll be null and we fall back to a generic line.
 */
function renderContactFooter(adminEmail: string | null | undefined): string {
  if (adminEmail) {
    return `Need help? Contact your LangWatch admin: ${adminEmail}\n`;
  }
  return `If you need help, contact your LangWatch admin.\n`;
}

/**
 * Pre-exec probe for `langwatch <tool>` wrappers. Three layered checks,
 * each gracefully degrading rather than blocking on transient hiccups:
 *
 *   1. `cfg.default_personal_vk?.secret` present - without it the
 *      wrapper would silently inject no env vars and the underlying
 *      tool would call the upstream provider directly (api.anthropic.com
 *      etc.), surfacing as the wrong error or - when there's stale
 *      env from a prior session - a confusing ConnectionRefused
 *      against a stale base URL.
 *   2. `GET <gateway_url>/healthz` reachable. Catches "data plane not
 *      running" and bad `LANGWATCH_GATEWAY_URL` overrides. Fatal: if
 *      the gateway isn't reachable the tool will spin in a retry loop
 *      and there's no recovery. We don't name a specific run command
 *      (`make`, helm chart, docker compose, `npx @langwatch/server`,
 *      etc.) because deployments vary; point the user at the admin
 *      contact instead.
 *   3. `getCliBootstrap()` providers cover the tool's family. Catches
 *      the shape where login succeeds but the org has no AI provider
 *      configured yet, so the gateway has nothing to route to. 404 /
 *      missing-providers data passes through (older self-hosted
 *      servers without the endpoint).
 *
 * Bootstrap is fetched up-front (it lives on the control plane,
 * independent of the gateway data plane) so every failure message can
 * embed the org admin's email as a real contact path. A bootstrap
 * error is non-fatal; we just lose the admin mailto and continue.
 */
export async function preflightWrapper(
  cfg: GovernanceConfig,
  tool: string,
  opts: PreflightOptions = {},
): Promise<PreflightResult> {
  const cp = cfg.control_plane_url.replace(/\/+$/, "");
  const bootstrap = await (opts.bootstrapImpl ?? getCliBootstrap)(cfg).catch(
    () => null,
  );
  const adminEmail = bootstrap?.adminEmail ?? null;

  if (!cfg.default_personal_vk?.secret) {
    return {
      ok: false,
      message:
        `No personal virtual key on this account.\n` +
        `Your organization needs at least one AI provider configured before\n` +
        `\`langwatch ${tool}\` can route requests.\n` +
        `If you're an admin, set one up at\n` +
        `  ${cp}/settings/model-providers\n` +
        `then run \`langwatch login --device\` to refresh your credentials.\n` +
        renderContactFooter(adminEmail),
    };
  }

  const gw = cfg.gateway_url.replace(/\/+$/, "");
  const f = opts.fetchImpl ?? fetch;
  const timeoutMs = opts.timeoutMs ?? 3000;
  try {
    const res = await f(`${gw}/healthz`, {
      method: "GET",
      signal: AbortSignal.timeout(timeoutMs),
    });
    if (!res.ok) {
      return {
        ok: false,
        retryable: true,
        message:
          `AI Gateway at ${gw} returned HTTP ${res.status}.\n` +
          `The wrapper cannot route \`langwatch ${tool}\` requests until the\n` +
          `data plane is healthy. Check that the LangWatch gateway is running.\n` +
          renderContactFooter(adminEmail),
      };
    }
  } catch (err) {
    return {
      ok: false,
      retryable: true,
      message:
        `Cannot reach AI Gateway at ${gw}\n` +
        `  ${(err as Error).message}\n` +
        `Check that the LangWatch gateway is running, or set LANGWATCH_GATEWAY_URL\n` +
        `if you've deployed it elsewhere.\n` +
        renderContactFooter(adminEmail),
    };
  }

  // The gateway program is opt-in per tool: an org enables it for a coding
  // assistant by publishing that tool's coding-assistant tile in the AI Tools
  // catalog. Without a tile for THIS tool the org hasn't turned the gateway on
  // for it (direct OTLP ingestion stays available separately), so don't route
  // a virtual key through it. `tools` undefined => legacy server that can't
  // report the catalog; skip the gate for back-compat.
  if (Array.isArray(bootstrap?.tools)) {
    const published = bootstrap.tools.some((t) => t.slug === tool);
    if (!published) {
      return {
        ok: false,
        message:
          `The gateway isn't enabled for \`${tool}\` in your organization.\n` +
          `An admin needs to publish a ${tool} coding-assistant tile in the\n` +
          `AI Tools catalog (with the gateway path enabled):\n` +
          `  ${cp}/settings/governance/tool-catalog\n` +
          renderContactFooter(adminEmail),
      };
    }
  }

  // The gateway routes through CONFIGURED provider credentials, not the curated
  // model_provider catalog tiles (those only gate the /me one-click "mint your
  // own VK" surface). Prefer the credential-derived families; fall back to the
  // tile list only on legacy servers that don't send `gatewayProviders`.
  const need = TOOL_PROVIDER_FAMILIES[tool];
  const configured =
    bootstrap?.gatewayProviders ?? bootstrap?.providers?.map((p) => p.name);
  if (need && need.length > 0 && Array.isArray(configured)) {
    const have = new Set(configured.map((n) => n.toLowerCase()));
    const matches = need.filter((n) => have.has(n));
    if (matches.length === 0) {
      const list = need.map((n) => `\`${n}\``).join(" or ");
      return {
        ok: false,
        message:
          `No ${list} provider credential is configured for your organization.\n` +
          `\`langwatch ${tool}\` needs at least one enabled provider to route\n` +
          `requests through the gateway. If you're an admin, add one at\n` +
          `  ${cp}/settings/model-providers\n` +
          renderContactFooter(adminEmail),
      };
    }
  }

  return { ok: true };
}

/**
 * When the wrapper is invoked without a usable config, decide whether to
 * auto-trigger the device-flow login inline or to fail fast. The device
 * flow needs a TTY (the user has to copy a code or click a browser link),
 * so default ON only when stdin is a TTY. CI/scripted callers can opt in
 * explicitly via `LANGWATCH_AUTO_LOGIN=1`, or opt out via
 * `LANGWATCH_AUTO_LOGIN=0` even on an interactive shell.
 */
function shouldAutoLogin(): boolean {
  const flag = process.env.LANGWATCH_AUTO_LOGIN;
  if (flag === "1" || flag === "true") return true;
  if (flag === "0" || flag === "false") return false;
  return Boolean(process.stdin.isTTY);
}

/**
 * Run the named tool routed through the gateway. Inherits stdio so
 * the user gets the same interactive UX they'd have invoking the
 * tool directly. Exits the parent process with the child's exit
 * code (or 2 if the budget pre-check fired).
 */
export async function runWrapped(tool: string, args: string[]): Promise<never> {
  let cfg = loadConfig();
  if (!isLoggedIn(cfg)) {
    if (!shouldAutoLogin()) {
      process.stderr.write(
        "Not logged in. Run `langwatch login --device` first.\n",
      );
      process.exit(1);
    }
    process.stderr.write(
      "Not logged in. Starting device-flow login...\n",
    );
    try {
      cfg = await runDeviceFlowLogin({ cfg });
    } catch (err) {
      process.stderr.write(
        `login failed: ${(err as Error).message ?? "unknown error"}\n`,
      );
      process.exit(1);
    }
    if (!isLoggedIn(cfg)) {
      process.stderr.write("login did not complete - exiting\n");
      process.exit(1);
    }
  }

  // Budget pre-check - render Screen-8 box + exit 2 BEFORE exec.
  const exceeded = await checkBudget(cfg);
  if (exceeded) {
    process.stderr.write(renderBudgetExceeded(exceeded));
    if (exceeded.request_increase_url) {
      cfg.last_request_increase_url = exceeded.request_increase_url;
      try {
        saveConfig(cfg);
      } catch {
        // Config write failure shouldn't change the spec'd exit
        // code - the next `langwatch request-increase` falls back
        // to the static page.
      }
    }
    process.exit(2);
  }

  // Strip the wrapper-only `--tool-mode` flag from the args BEFORE anything
  // forwards them to the real tool, and resolve any explicit override.
  // Everything else stays verbatim + in order for the child invocation.
  const { args: toolArgs, override: pathOverride } = parseToolModeFlag(args);

  // Decide Path A (gateway) vs Path B (ingestion) for this run. Prompts
  // (and remembers the answer) only when the org policy allows BOTH paths,
  // stdin/stdout is a TTY, and there's no pinned preference / override.
  // Runs BEFORE env injection + spawn so the prompt owns stdin.
  let pathChoice;
  try {
    pathChoice = await resolveWrapperPath({
      cfg,
      tool,
      args: toolArgs,
      override: pathOverride,
      // Re-check the org policy at run time so a path the admin disabled
      // after login is respected without a re-login. Best-effort: on any
      // failure resolveWrapperPath keeps the login-cached policy map.
      refreshPolicies: (c) =>
        getCliBootstrap(c).then((b) => b?.toolPolicies ?? null),
    });
  } catch (err) {
    process.stderr.write(`path selection failed: ${(err as Error).message}\n`);
    process.exit(2);
  }

  const toolEnv = envForTool(cfg, tool);
  const gatewayVars = toolEnv.vars;
  const gatewayClears = toolEnv.clears ?? [];
  let modeResult;
  try {
    modeResult = await resolveWrapperMode(
      cfg,
      tool,
      gatewayVars,
      gatewayClears,
      pathChoice.mode,
    );
  } catch (err) {
    // Path B (ingestion) setup can fail at mint time - e.g. the user has
    // no personal workspace yet, or the control plane is unreachable. If
    // the gateway path is allowed for this tool, surface a clear message
    // and fall back to it rather than dead-ending. The both-paths-off
    // `tool_disabled` policy error is NOT a mint failure, so it never
    // falls back; it exits with the admin hint.
    const isToolDisabled =
      err instanceof GovernanceCliError && err.code === "tool_disabled";
    const policy = resolvePlatformToolPolicy(tool, cfg.tool_policies);
    if (pathChoice.mode === "ingestion" && policy.allowVk && !isToolDisabled) {
      process.stderr.write(
        `${lwTag()} couldn't set up direct OTLP ingestion for ${tool} ` +
          `(${(err as Error).message}). Falling back to the gateway path.\n`,
      );
      try {
        modeResult = await resolveWrapperMode(
          cfg,
          tool,
          gatewayVars,
          gatewayClears,
          "gateway",
        );
      } catch (err2) {
        process.stderr.write(
          `mode resolution failed: ${(err2 as Error).message}\n`,
        );
        process.exit(2);
      }
    } else {
      process.stderr.write(
        `mode resolution failed: ${(err as Error).message}\n`,
      );
      process.exit(2);
    }
  }

  // Surface any platform-policy path change (e.g. the org admin turned
  // direct OTLP off for this tool, so the wrapper routed through the
  // gateway instead) so the member sees why the path differs.
  if (modeResult.notice) {
    process.stderr.write(`${modeResult.notice}\n`);
  }

  if (modeResult.mode === "gateway") {
    const probe = await preflightWrapper(cfg, tool);
    if (!probe.ok) {
      process.stderr.write(probe.message ?? "preflight failed\n");
      // A remembered gateway choice that can't actually serve this account/org
      // (no virtual key / no provider configured) would re-fail every run. Drop
      // the pin so the next run re-asks and the user can pick direct OTLP. A
      // transient gateway-down failure keeps the pin (a retry may succeed).
      if (
        shouldForgetGatewayPin({
          pinnedMode: cfg.tool_mode?.[tool],
          retryable: probe.retryable,
        })
      ) {
        const toolMode = { ...cfg.tool_mode };
        delete toolMode[tool];
        cfg.tool_mode = toolMode;
        try {
          saveConfig(cfg);
          process.stderr.write(
            `${lwTag()} cleared the saved gateway path for \`${tool}\`; ` +
              `you'll be asked again next time so you can pick direct OTLP.\n`,
          );
        } catch {
          // Best-effort: a config write failure just leaves the pin in place.
        }
      }
      process.exit(2);
    }
    if (modeResult.codexConfigPath) {
      process.stderr.write(
        `${lwTag()} wired [model_providers.langwatch] in ${modeResult.codexConfigPath}.\n`,
      );
    }
    if (modeResult.codexProfilePath) {
      process.stderr.write(
        `${lwTag()} wrote profile body to ${modeResult.codexProfilePath}.\n`,
      );
    }
  } else {
    // ingestion mode side-effect feedback so the user sees what
    // the wrapper just did on their behalf.
    if (modeResult.newKeyMinted) {
      process.stderr.write(
        `${lwTag()} minted a personal ingestion key for ${tool}.\n`,
      );
    }
    if (modeResult.codexConfigPath) {
      process.stderr.write(
        `${lwTag()} wrote [otel] activation block to ${modeResult.codexConfigPath}.\n`,
      );
    }

    // Path B only: offer to persist the OTLP telemetry exports so a future
    // plain `<tool>` (without the langwatch wrapper) captures
    // automatically. Gated on ingestion mode + opt-out remembered. Runs
    // BEFORE spawn so the prompt still owns stdin.
    await maybeOfferIngestionShellRcPersist({
      cfg,
      tool,
      vars: modeResult.vars,
    });
  }

  // Scrub conflicting twins from the inherited parent env BEFORE merging
  // our vars in. The clears list per tool exists because legacy creds
  // exported in the user's shell (e.g. ANTHROPIC_API_KEY from direct
  // Anthropic SDK usage) would otherwise race with the gateway-routed
  // ANTHROPIC_AUTH_TOKEN we set, surfacing as the claude-code warning
  // "Both ANTHROPIC_AUTH_TOKEN and ANTHROPIC_API_KEY set, auth may not
  // work as expected" and, worse, occasionally letting the SDK pick the
  // wrong credential.
  const parentEnv = { ...process.env };
  for (const key of modeResult.clears ?? []) {
    delete parentEnv[key];
  }
  const env = { ...parentEnv, ...modeResult.vars };
  // Forward the user's args verbatim and in order, minus the stripped
  // wrapper flag (`--tool-mode`). Any mode-specific prepends (e.g. codex
  // `--profile langwatch-gateway`) lead.
  const finalArgs = [...(modeResult.extraArgs ?? []), ...toolArgs];

  // Resolve the tool the way the user's own shell would: route it through
  // their interactive login shell (zsh/bash) so aliases AND functions are
  // honored - e.g. `alias claude='claude --dangerously-skip-permissions'`,
  // not just the bare PATH binary. `-i` sources the rc file where aliases
  // live; the wrapper's env (mode vars + clears) is re-applied *after* that
  // so a user's rc can't clobber the gateway / OTLP wiring. Args ride
  // positional params ("$@") and are never re-quoted. `tool` is whitelisted
  // (claude/codex/cursor/gemini/opencode) so the command string is safe.
  const shellName = (process.env.SHELL ?? "").split("/").pop() ?? "";
  const aliasShell =
    process.platform !== "win32" && (shellName === "zsh" || shellName === "bash")
      ? process.env.SHELL!
      : null;

  const notFoundMessage = `${tool} not found in PATH - install it first (https://docs.langwatch.ai/ai-gateway/governance/admin-setup#cli-device-flow-rest-api)`;

  // Stamp the session start so the codex rollout harvest only reads rollout
  // files this run produced (codex names them by start time + mtime).
  const sessionStartMs = Date.now();

  // Codex never puts the prompt or the assistant reply on the wire (its OTLP
  // spans carry tokens + model only), but it writes the full transcript to an
  // append-only rollout file whose per-turn `task_started` records the exact
  // OTLP trace_id. Poll it WHILE codex runs and emit each turn the moment it
  // completes, so content streams in per turn instead of one multi-megabyte
  // burst on exit. The poll plus a final sweep on close are idempotent (the
  // per-turn span id is trace_id-derived), so overlap dedups server-side.
  const codexStreamer =
    tool === "codex" &&
    modeResult.mode === "ingestion" &&
    modeResult.endpoint &&
    modeResult.ingestionToken
      ? createCodexIOStreamer({
          sinceMs: sessionStartMs,
          endpoint: `${modeResult.endpoint.replace(/\/+$/, "")}/v1/traces`,
          token: modeResult.ingestionToken,
        })
      : null;
  let codexPoll: ReturnType<typeof setInterval> | null = null;
  if (codexStreamer) {
    let inFlight = false;
    codexPoll = setInterval(() => {
      // Skip a tick if the previous harvest (file read + POST, ≤5s) is still
      // running so slow ticks can't pile up.
      if (inFlight) return;
      inFlight = true;
      void codexStreamer
        .harvest(Date.now())
        .catch(() => 0)
        .finally(() => {
          inFlight = false;
        });
    }, CODEX_IO_POLL_MS);
    // The child process drives the lifecycle; never let the poll keep the event
    // loop alive on its own.
    codexPoll.unref?.();
  }

  let child;
  if (aliasShell) {
    const q = (s: string) => `'${s.replace(/'/g, "'\\''")}'`;
    const reapply = [
      ...(modeResult.clears ?? []).map((k) => `unset ${k}`),
      ...Object.entries(modeResult.vars).map(([k, v]) => `export ${k}=${q(v)}`),
    ].join("; ");
    // Resolve the tool inside the same login shell before handing over so a
    // missing tool surfaces our actionable message rather than a bare
    // `command not found`. `command -v` honors the aliases/functions/PATH the
    // spawn below would use. The direct-spawn branch relies on ENOENT instead.
    const guard = `command -v -- ${q(tool)} >/dev/null 2>&1 || { printf '%s\\n' ${q(notFoundMessage)} >&2; exit 127; }`;
    const command = `${reapply ? `${reapply}; ` : ""}${guard}; ${tool} "$@"`;
    child = spawn(aliasShell, ["-i", "-c", command, tool, ...finalArgs], {
      stdio: "inherit",
      env,
    });
  } else {
    // Windows (npm installs the tools as `.cmd` shims, so resolve via the
    // shell) or a shell we don't special-case (fish, etc.): spawn directly.
    child = spawn(tool, finalArgs, {
      stdio: "inherit",
      env,
      shell: process.platform === "win32",
    });
  }
  child.on("error", (err) => {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") {
      process.stderr.write(`${notFoundMessage}\n`);
      process.exit(127);
    }
    process.stderr.write(`exec ${tool}: ${err.message}\n`);
    process.exit(1);
  });
  const exitCode = await new Promise<number>((resolve) => {
    child.on("close", (code) => resolve(code ?? 1));
  });

  // Stop polling and do one final sweep so the last turn (completed between the
  // last poll and exit) still lands. Best-effort: a coding session must never
  // fail or stall on the content harvest.
  if (codexPoll) clearInterval(codexPoll);
  if (codexStreamer) {
    try {
      await codexStreamer.harvest(Date.now());
    } catch {
      /* content recovery is non-essential; never block exit on it */
    }
  }

  process.exit(exitCode);
}
","import chalk from "chalk";

/** LangWatch accent orange, used to tint the CLI notice tag. */
const LANGWATCH_ORANGE = "#ED8926";

/**
 * The styled `langwatch` tag that prefixes wrapper notices. A small spark
 * plus the brand name in bold orange so the chatter reads as LangWatch and
 * not a generic log line. chalk auto-strips the color when stdout is not a
 * TTY (piped / CI), so plain-text consumers still get `✦ langwatch ...`.
 *
 * Replaces the flat `langwatch:` prefix. Call sites read as a sentence,
 * e.g. `${lwTag()} saved.` -> "✦ langwatch saved.".
 */
export function lwTag(): string {
  return chalk.hex(LANGWATCH_ORANGE).bold("✦ langwatch");
}
","/**
 * Pre-exec budget probe + Screen-8 ASCII renderer for the langwatch
 * wrappers (`langwatch claude` / `codex` / `cursor` / `gemini`).
 *
 * Per `specs/ai-gateway/governance/budget-exceeded.feature`: before
 * any wrapped command exec's the underlying tool, the CLI hits
 * `GET /api/auth/cli/budget/status`. On 402, render the spec
 * canonical box and exit 2 (configuration / quota error) without
 * spawning the tool.
 */

import { type GovernanceConfig } from "./config";

export interface BudgetExceededPayload {
  type: string;
  scope: "user" | "team" | "org" | "project";
  limit_usd: string;
  spent_usd: string;
  period: string; // "month" | "week" | "day" | ...
  request_increase_url?: string;
  admin_email?: string;
}

export interface CheckBudgetOptions {
  fetchImpl?: typeof fetch;
}

/**
 * Returns the 402 payload if the user is currently blocked, null
 * otherwise. 404 is treated as "older self-hosted server doesn't
 * expose this endpoint yet — pass through" so the CLI degrades
 * gracefully against legacy deploys. Network/5xx/etc. also
 * pass-through (the gateway's own 402 will surface via the wrapped
 * tool's error rendering as a fallback).
 */
export async function checkBudget(
  cfg: GovernanceConfig,
  opts: CheckBudgetOptions = {},
): Promise<BudgetExceededPayload | null> {
  if (!cfg.access_token) return null;
  const f = opts.fetchImpl ?? fetch;
  const url = cfg.control_plane_url.replace(/\/+$/, "") + "/api/auth/cli/budget/status";
  let res: Response;
  try {
    res = await f(url, {
      method: "GET",
      headers: {
        Authorization: `Bearer ${cfg.access_token}`,
        Accept: "application/json",
      },
    });
  } catch {
    return null; // network error — never block the user on this check
  }
  if (res.status === 200) return null;
  if (res.status === 404) return null; // older server, no endpoint yet
  if (res.status === 402) {
    try {
      const body = (await res.json()) as { error?: BudgetExceededPayload };
      if (body.error?.type && body.error.scope) return body.error;
    } catch {
      // malformed payload — fall through, let the underlying tool's
      // error render whatever the gateway returns
    }
  }
  return null;
}

/**
 * Spec-canonical Screen-8 box. ASCII only — no ANSI codes — so
 * piping `langwatch claude | tee log` doesn't litter the log with
 * escape sequences. Lines match the budget-exceeded.feature
 * scenario character-for-character.
 */
// Gateway emits root-form periods from the `GatewayBudgetWindow` Prisma
// enum lowercased ("month", "week", "day", "hour", "minute", "total").
// Naive `${period}ly` produces "dayly" / "totally" / "minutely" — map
// explicitly. Unknown periods (e.g. older server adds "rolling_24h")
// fall through to the raw value rather than render gibberish.
const PERIOD_LABEL: Record<string, string> = {
  minute: "per-minute",
  hour: "hourly",
  day: "daily",
  week: "weekly",
  month: "monthly",
  total: "total",
};

export function renderBudgetExceeded(e: BudgetExceededPayload): string {
  const period = (e.period || "month").toLowerCase();
  const periodLabel = PERIOD_LABEL[period] ?? period;
  const lines: string[] = [];
  lines.push("⚠  Budget limit reached");
  lines.push("");
  lines.push(`   You've used $${e.spent_usd} of your $${e.limit_usd} ${periodLabel} budget.`);
  lines.push("   To continue, ask your team admin to raise your limit.");
  lines.push("");
  if (e.admin_email) {
    lines.push(`   Admin: ${e.admin_email}`);
    lines.push("");
  }
  lines.push("   Need urgent access? Run:");
  lines.push("     langwatch request-increase");
  return lines.join("\n") + "\n";
}
","/**
 * Platform-tool policy table.
 *
 * Per-tool toggles that gate the two `langwatch <tool>` paths the
 * wrapper can take:
 *
 *   - allowVk: tool may route through the gateway via the user's
 *     personal VK (Path A). When false, the wrapper forces Path B
 *     even if a VK is present.
 *   - allowOtelDirect: tool may route via OTLP straight to
 *     `/api/otel/v1/logs` with the user's ingestion key (Path B).
 *     When false, the wrapper refuses to install Path B and surfaces
 *     a clear error.
 *
 * The resolver prefers the policy map the CLI cached at login
 * (`cfg.tool_policies`, served by the control plane's
 * PlatformToolPolicyService) and falls back to the hardcoded defaults
 * below when the cache is absent: an offline or legacy CLI that never
 * cached a map, or a tool the server did not return. The defaults must
 * stay in sync with the server-side PLATFORM_TOOL_POLICY_DEFAULTS.
 */

export type PlatformToolSlug =
  | "claude"
  | "codex"
  | "gemini"
  | "opencode"
  | "cursor";

export interface PlatformToolPolicy {
  allowVk: boolean;
  allowOtelDirect: boolean;
}

/**
 * The login-cached policy map. Comes from config.json (untyped JSON),
 * so every slug is optional and a missing entry falls back to the
 * hardcoded default.
 */
export type PlatformToolPolicyMap = Partial<Record<string, PlatformToolPolicy>>;

const DEFAULTS: PlatformToolPolicy = {
  allowVk: true,
  allowOtelDirect: true,
};

export const PLATFORM_TOOL_POLICIES: Record<PlatformToolSlug, PlatformToolPolicy> = {
  claude: { ...DEFAULTS },
  codex: { ...DEFAULTS },
  gemini: { ...DEFAULTS },
  opencode: { ...DEFAULTS },
  // cursor is GUI-only; Path B is not meaningful (no terminal env
  // reaches the agent panel). The wrapper still gates on this so
  // future GUI integrations can flip allowOtelDirect to true.
  cursor: { allowVk: true, allowOtelDirect: false },
};

function hardcodedPolicy(toolSlug: string): PlatformToolPolicy {
  if (toolSlug in PLATFORM_TOOL_POLICIES) {
    return PLATFORM_TOOL_POLICIES[toolSlug as PlatformToolSlug];
  }
  return DEFAULTS;
}

/**
 * Resolve the policy for a given tool slug. Prefers the login-cached
 * server map when it carries an entry for the tool; otherwise falls
 * back to the hardcoded defaults. A non-platform slug (typo) also
 * resolves to DEFAULTS so the wrapper never crashes.
 */
export function resolvePlatformToolPolicy(
  toolSlug: string,
  cachedPolicies?: PlatformToolPolicyMap,
): PlatformToolPolicy {
  const cached = cachedPolicies?.[toolSlug];
  if (cached) return cached;
  return hardcodedPolicy(toolSlug);
}
","/**
 * Persist the langwatch export block to the user's shell rc file
 * (~/.zshrc / ~/.bashrc / ~/.config/fish/config.fish) so a new
 * shell auto-picks up the gateway + OTLP env vars without running
 * `langwatch <tool>` as a wrapper.
 *
 * Spec for bug-bash item 1:
 *   1.2 - after login, OFFER to persist the export block. Y/n/never.
 *   1.3 - Remember choice. Stay quiet inside an already-configured
 *         shell (env already has the gateway vars set).
 *
 * Design notes:
 *   - The block is bracketed with marker comments so a second
 *     persist run is idempotent (regex replace, no duplicate
 *     blocks).
 *   - "never" persists `shell_rc_preference: "skip"` on the config
 *     so future logins on this machine stay quiet.
 *   - "not now" (n) does NOT persist - the next login re-asks. The
 *     in-shell quietness comes from the already-configured detect.
 *   - Detect "already configured" by checking process.env for both
 *     ANTHROPIC_BASE_URL and ANTHROPIC_AUTH_TOKEN. If either is
 *     present, assume the user already wired it up (via the rc
 *     file or by sourcing the export manually) and skip the
 *     prompt silently.
 */

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import * as readline from "node:readline";

import chalk from "chalk";

import {
  codexOtelBlockHasAuthHeader,
  codexTraceEndpoint,
  defaultCodexConfigPath,
  displayCodexConfigPath,
  writeCodexOtelBlock,
} from "../codex-config-toml";
import {
  appEnvHasAllVars,
  appSettingsTargetFor,
  installAppEnv,
} from "./app-settings";
import { type GovernanceConfig, saveConfig } from "./config";
import { envForTool, type ToolEnv } from "./wrapper";

/** Wrapped tools included in the union'd export block. */
const TOOLS = ["claude", "codex", "cursor", "gemini", "opencode"] as const;

const BLOCK_BEGIN = "# >>> langwatch begin >>>";
const BLOCK_END = "# <<< langwatch end <<<";

/** Markers for the global gateway export block (init-shell / legacy persist). */
export const GATEWAY_RC_MARKERS = { begin: BLOCK_BEGIN, end: BLOCK_END };

/**
 * Per-tool marker pair for a scoped wrapper function. Tools without a
 * config-file env target (gemini, opencode, …) get a shell function that
 * sets the telemetry env ONLY for `<tool>` invocations, instead of a global
 * `export` that leaks into every shell child. Each tool gets its own marker
 * pair so multiple wrappers coexist in one rc file.
 */
export function toolMarkers(tool: string): { begin: string; end: string } {
  return {
    begin: `# >>> langwatch ${tool} begin >>>`,
    end: `# <<< langwatch ${tool} end <<<`,
  };
}

export type DetectedShell = "zsh" | "bash" | "fish";

/**
 * Best-effort shell detection from $SHELL. Falls back to zsh on
 * macOS (default since Catalina) and bash on Linux. Returns null
 * when running under an unsupported shell (cmd, powershell, etc.)
 * - the persist flow skips entirely in that case.
 */
export function detectShell(): DetectedShell | null {
  const raw = (process.env.SHELL ?? "").toLowerCase();
  if (raw.includes("fish")) return "fish";
  if (raw.includes("zsh")) return "zsh";
  if (raw.includes("bash")) return "bash";
  if (process.platform === "darwin") return "zsh";
  if (process.platform === "linux") return "bash";
  return null;
}

/** Returns the absolute path of the shell rc file. */
export function rcPath(shell: DetectedShell): string {
  const home = os.homedir();
  switch (shell) {
    case "zsh":
      return path.join(home, ".zshrc");
    case "bash":
      return path.join(home, ".bashrc");
    case "fish":
      return path.join(home, ".config", "fish", "config.fish");
  }
}

/**
 * Whether the current shell already has the gateway env vars
 * exported. If true the persist prompt stays quiet (per 1.3).
 */
export function isShellAlreadyConfigured(): boolean {
  return (
    !!process.env.ANTHROPIC_BASE_URL && !!process.env.ANTHROPIC_AUTH_TOKEN
  );
}

/**
 * Whether the shell rc file already has a langwatch marker block carrying
 * THIS export set. Lets the persist offer stay quiet when the user has
 * already installed the current exports but hasn't sourced the rc in this
 * shell yet (so the env isn't live in process.env). Checks the file on
 * disk, not just the environment.
 *
 * `requiredKeys` makes the match export-set aware: a bare marker block, or
 * a block for a DIFFERENT export set (e.g. a stale block missing the OTLP
 * vars this run needs), does NOT count as installed, so the offer still
 * fires and persists the current vars. Omit `requiredKeys` to test only
 * for the presence of a well-formed block.
 */
export function rcHasLangwatchBlock({
  shell,
  requiredKeys,
  markers = { begin: BLOCK_BEGIN, end: BLOCK_END },
}: {
  shell: DetectedShell;
  requiredKeys?: string[];
  markers?: { begin: string; end: string };
}): boolean {
  try {
    const content = fs.readFileSync(rcPath(shell), "utf8");
    const begin = content.indexOf(markers.begin);
    const end = content.indexOf(markers.end);
    if (begin === -1 || end === -1 || end < begin) return false;
    if (!requiredKeys || requiredKeys.length === 0) return true;
    const block = content.slice(begin, end);
    return requiredKeys.every((k) => block.includes(k));
  } catch {
    return false;
  }
}

/**
 * Build the export-block body (without the begin/end markers) for
 * the given shell. Iterates the 5 wrapped tools and dedups env keys
 * so a multi-provider tool (cursor / opencode) doesn't repeat
 * OPENAI_* + ANTHROPIC_*.
 */
export function buildExportBlock(
  cfg: GovernanceConfig,
  shell: DetectedShell,
): string {
  const seen = new Set<string>();
  const entries: Array<[string, string]> = [];
  for (const tool of TOOLS) {
    const env: ToolEnv = envForTool(cfg, tool);
    for (const [k, v] of Object.entries(env.vars)) {
      if (seen.has(k)) continue;
      seen.add(k);
      entries.push([k, v]);
    }
  }
  const fmt =
    shell === "fish"
      ? ([k, v]: [string, string]) => `set -gx ${k} ${quote(v)}`
      : ([k, v]: [string, string]) => `export ${k}=${quote(v)}`;
  return entries.map(fmt).join("\n");
}

function quote(s: string): string {
  if (!/[ \t\n'"$\\]/.test(s)) return s;
  return "'" + s.replace(/'/g, "'\\''") + "'";
}

/**
 * Build a shell function that wraps `<tool>` so the OTEL telemetry env is
 * set ONLY for `<tool>` invocations, not exported into every shell child.
 * This is the fallback for any tool with no config-file env target (gemini,
 * opencode, …): `command <tool>` inside the function bypasses the function
 * itself (no recursion) and runs the real binary.
 *
 * posix (zsh/bash) uses a function with an env-prefix; fish uses a function
 * with block-local `set -lx`. The body (no begin/end markers) is returned
 * for `persistBlockToRc` to bracket with the tool's markers.
 */
export function buildScopedToolFunction(
  tool: string,
  vars: Record<string, string>,
  shell: DetectedShell,
): string {
  const entries = Object.entries(vars);
  if (shell === "fish") {
    const sets = entries
      .map(([k, v]) => `    set -lx ${k} ${quote(v)}`)
      .join("\n");
    return [
      `function ${tool}`,
      sets,
      `    command ${tool} $argv`,
      "end",
    ].join("\n");
  }
  const assigns = entries
    .map(([k, v]) => `    ${k}=${quote(v)} \\`)
    .join("\n");
  return [`${tool}() {`, assigns, `    command ${tool} "$@"`, "}"].join("\n");
}

/**
 * Append (or replace, if the marker block already exists) the
 * export block to the shell rc file. Creates the file if missing.
 * Idempotent: a second run replaces the block in place rather
 * than duplicating it.
 *
 * Returns the path that was written for the caller to surface.
 */
export function persistBlockToRc(
  shell: DetectedShell,
  block: string,
  markers: { begin: string; end: string } = {
    begin: BLOCK_BEGIN,
    end: BLOCK_END,
  },
): string {
  const file = rcPath(shell);
  const dir = path.dirname(file);
  fs.mkdirSync(dir, { recursive: true });
  const wrapped = `${markers.begin}\n${block}\n${markers.end}\n`;

  let existing = "";
  try {
    existing = fs.readFileSync(file, "utf8");
  } catch {
    // ENOENT - fresh file
  }

  const marker = new RegExp(
    `${escapeRegex(markers.begin)}[\\s\\S]*?${escapeRegex(markers.end)}\\n?`,
    "m",
  );
  let next: string;
  if (marker.test(existing)) {
    next = existing.replace(marker, wrapped);
  } else {
    const needsNewline = existing.length > 0 && !existing.endsWith("\n");
    next = existing + (needsNewline ? "\n" : "") + "\n" + wrapped;
  }
  fs.writeFileSync(file, next);
  return file;
}

function escapeRegex(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/**
 * Remove a marker-bracketed langwatch block from the shell rc file, if
 * present. Removes at most one leading + one trailing newline around the
 * block, so the blank line the install path inserts before it goes with it
 * while unrelated user whitespace is left alone. Returns true when a block
 * was removed (idempotent — false when the file or the block was absent).
 */
export function removeBlockFromRc(
  shell: DetectedShell,
  markers: { begin: string; end: string } = {
    begin: BLOCK_BEGIN,
    end: BLOCK_END,
  },
): boolean {
  const file = rcPath(shell);
  let content: string;
  try {
    content = fs.readFileSync(file, "utf8");
  } catch {
    return false; // ENOENT
  }
  const re = new RegExp(
    `\\n?${escapeRegex(markers.begin)}[\\s\\S]*?${escapeRegex(markers.end)}\\n?`,
    "m",
  );
  if (!re.test(content)) return false;
  fs.writeFileSync(file, content.replace(re, ""));
  return true;
}

/**
 * Y/n/never prompt for stdin. Returns:
 *   - "yes" → append the block now
 *   - "no" → skip this login, re-ask next time
 *   - "never" → set shell_rc_preference=skip so we stay quiet forever
 *   - "skip" → non-TTY / closed stdin; do nothing
 */
export type PersistChoice = "yes" | "no" | "never" | "skip";

export async function askPersistChoice(
  rcPathHint: string,
  tool: string,
): Promise<PersistChoice> {
  if (!process.stdin.isTTY) return "skip";

  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  });
  const ans = await new Promise<string>((resolve) => {
    rl.question(
      `Install env vars to ${rcPathHint} so that next time the plain \`${tool}\` command keeps capturing telemetry data? [Y/n/never] `,
      (a) => resolve(a),
    );
  });
  rl.close();

  const norm = ans.trim().toLowerCase();
  if (norm === "" || norm === "y" || norm === "yes") return "yes";
  if (norm === "never") return "never";
  return "no";
}

/**
 * Ingestion-mode (Path B) persist offer. Called by the
 * `langwatch <tool>` wrapper AFTER it resolves to ingestion mode,
 * so the user can install the tool's OTLP telemetry exports into
 * whatever the target for `<tool>` is. Once persisted, a plain
 * `<tool>` invocation (without the `langwatch` wrapper) inherits
 * the OTEL_EXPORTER_OTLP_* env and captures automatically - which
 * is the whole point of "installing" the telemetry.
 *
 * The target depends on the tool:
 *   - `claude` writes to `~/.claude/settings.json`'s `env` block
 *     — Claude Code loads that on every invocation, so the vars
 *     stay scoped to `claude` runs and don't leak into every
 *     other shell child.
 *   - Every other supported wrapper (codex, cursor, gemini,
 *     opencode) falls back to the detected shell rc file.
 *
 * Persists the exact OTEL env the wrapper just computed for this
 * run (`vars`), not the gateway block. Y / n / never, same
 * `shell_rc_preference=skip` opt-out. Stays quiet when the target
 * already carries the current export set.
 */
export async function maybeOfferIngestionShellRcPersist({
  cfg,
  tool,
  vars,
}: {
  cfg: GovernanceConfig;
  tool: string;
  vars: Record<string, string>;
}): Promise<void> {
  if (cfg.shell_rc_preference === "skip") return;
  // Already wired up - the OTLP exporter env is present in this shell.
  if (process.env.OTEL_EXPORTER_OTLP_ENDPOINT) return;
  if (Object.keys(vars).length === 0) return;

  const appTarget = appSettingsTargetFor(tool);
  if (appTarget) {
    if (appEnvHasAllVars(appTarget, vars)) return;
    console.log();
    const choice = await askPersistChoice(appTarget.displayPath, tool);
    if (choice === "skip" || choice === "no") return;
    if (choice === "never") {
      recordNeverChoice(cfg);
      return;
    }
    try {
      installAppEnv(appTarget, vars);
      console.log(
        chalk.green(
          `  ✓ Installed langwatch telemetry exports to ${appTarget.displayPath}`,
        ),
      );
    } catch (err) {
      console.log(
        chalk.yellow(
          `  ! Couldn't write to ${appTarget.displayPath}: ${(err as Error).message}`,
        ),
      );
    }
    return;
  }

  // codex has a native app-scoped target too: its [otel] block in
  // ~/.codex/config.toml takes an inline Authorization header, so the
  // ingest token scopes to codex runs instead of leaking into every
  // shell child via the profile rc. The wrapper already wrote the
  // endpoint-only block during setup; persisting adds the header so a
  // plain `codex` captures.
  if (tool === "codex") {
    const configPath = defaultCodexConfigPath();
    // Already persisted on a prior run — stay quiet.
    if (codexOtelBlockHasAuthHeader(configPath)) return;

    const endpointBase = vars.OTEL_EXPORTER_OTLP_ENDPOINT;
    const token = bearerFromHeaders(vars.OTEL_EXPORTER_OTLP_HEADERS);
    if (!endpointBase || !token) return;

    console.log();
    const choice = await askPersistChoice(displayCodexConfigPath(), tool);
    if (choice === "skip" || choice === "no") return;
    if (choice === "never") {
      recordNeverChoice(cfg);
      return;
    }
    try {
      writeCodexOtelBlock(
        {
          endpoint: codexTraceEndpoint(endpointBase),
          ingestionToken: token,
          environment: cfg.organization?.slug ?? "langwatch",
        },
        { persistAuthHeader: true },
      );
      console.log(
        chalk.green(
          `  ✓ Installed langwatch telemetry exports to ${displayCodexConfigPath()}`,
        ),
      );
    } catch (err) {
      console.log(
        chalk.yellow(
          `  ! Couldn't write to ${displayCodexConfigPath()}: ${(err as Error).message}`,
        ),
      );
    }
    return;
  }

  const shell = detectShell();
  if (!shell) return;

  // Every remaining tool (gemini, opencode, …) has no config-file env target
  // and rides on generic OTEL_* names, so a global `export` would leak into
  // every shell child. Install a scoped wrapper function that sets the
  // telemetry env only for `<tool>` runs, under the tool's own marker pair so
  // multiple wrappers coexist. (cursor never reaches here — it's gateway-only
  // via allow_otel_direct=false, so Path B ingestion never resolves for it.)
  const markers = toolMarkers(tool);
  // Already installed for this endpoint, even if this shell hasn't sourced the
  // rc yet (so the OTEL env isn't in process.env). Keyed on the endpoint so a
  // stale wrapper for a different endpoint doesn't suppress installing this one.
  if (
    rcHasLangwatchBlock({
      shell,
      requiredKeys: [vars.OTEL_EXPORTER_OTLP_ENDPOINT].filter(
        Boolean,
      ) as string[],
      markers,
    })
  ) {
    return;
  }
  const target = rcPath(shell);
  console.log();
  const choice = await askPersistChoice(target, tool);
  if (choice === "skip" || choice === "no") return;
  if (choice === "never") {
    recordNeverChoice(cfg);
    return;
  }
  try {
    const wrote = persistBlockToRc(
      shell,
      buildScopedToolFunction(tool, vars, shell),
      markers,
    );
    console.log(
      chalk.green(
        `  ✓ Installed a scoped \`${tool}\` telemetry wrapper in ${wrote}`,
      ),
    );
  } catch (err) {
    console.log(
      chalk.yellow(`  ! Couldn't write to ${target}: ${(err as Error).message}`),
    );
  }
}

function recordNeverChoice(cfg: GovernanceConfig): void {
  cfg.shell_rc_preference = "skip";
  try {
    saveConfig(cfg);
  } catch {
    // best effort — a config write failure just means the next run re-asks.
  }
}

/**
 * Pull the bearer token out of an `OTEL_EXPORTER_OTLP_HEADERS` value
 * shaped like `Authorization=Bearer <token>`. Returns null when the
 * header is absent or malformed.
 */
function bearerFromHeaders(headers: string | undefined): string | null {
  if (!headers) return null;
  const m = /Bearer\s+(\S+)/.exec(headers);
  return m ? m[1]! : null;
}
","/**
 * Persist Path B (ingestion) telemetry env vars into a tool's own
 * settings file, rather than the profile-root shell rc.
 *
 * Motivation: `langwatch claude` used to offer to write its
 * OTEL_EXPORTER_OTLP_* block to `~/.zshrc`. That works, but it
 * leaks the vars into every other shell child (git, ripgrep,
 * unrelated services) and pollutes the profile root. Claude Code
 * has a native, per-app `env` block in `~/.claude/settings.json`
 * that it loads on every invocation — writing there scopes the
 * telemetry to `claude` runs only.
 *
 * For scope: `claude` is the only tool with a supported target
 * today. Other wrappers (codex, cursor, gemini, opencode) still
 * fall back to the shell rc path. Adding a new tool means adding
 * an entry to `TARGETS` below and (if the format isn't JSON with
 * a top-level `env` map) extending the read/write helpers.
 */

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";

export interface AppSettingsTarget {
  /** Tool slug the target belongs to (e.g. "claude"). */
  tool: string;
  /** Absolute path to the settings file on disk. */
  path: string;
  /** Human-readable path shown in the prompt (`~/.claude/settings.json`). */
  displayPath: string;
}

interface TargetSpec {
  /** Path segments below the user's home dir. */
  segments: string[];
}

const TARGETS: Record<string, TargetSpec> = {
  claude: { segments: [".claude", "settings.json"] },
};

/**
 * Return the settings target for a tool, or null when the tool has
 * no supported app-scoped env block (caller should fall back to the
 * shell rc path).
 */
export function appSettingsTargetFor(tool: string): AppSettingsTarget | null {
  const spec = TARGETS[tool];
  if (!spec) return null;
  const home = os.homedir();
  return {
    tool,
    path: path.join(home, ...spec.segments),
    displayPath: `~/${spec.segments.join("/")}`,
  };
}

/**
 * Whether the target's `env` map already contains every required
 * key with the required value. Used to stay quiet when a previous
 * run already installed the current export set (so re-running
 * `langwatch <tool>` doesn't nag).
 */
export function appEnvHasAllVars(
  target: AppSettingsTarget,
  vars: Record<string, string>,
): boolean {
  const current = readEnvMap(target.path);
  for (const [k, v] of Object.entries(vars)) {
    if (current[k] !== v) return false;
  }
  return true;
}

/**
 * Whether the target's `env` map contains ANY of `keys`. Used by the
 * logout scan to decide whether a claude telemetry block is present to
 * offer for removal.
 */
export function appEnvHasAnyVar(
  target: AppSettingsTarget,
  keys: string[],
): boolean {
  const current = readEnvMap(target.path);
  return keys.some((k) => k in current);
}

/**
 * Merge `vars` into the target's top-level `env` map, creating
 * parent directories and the file itself when missing. Preserves
 * every other user-authored top-level key verbatim. Values in
 * `vars` win over pre-existing entries under the same key.
 */
export function installAppEnv(
  target: AppSettingsTarget,
  vars: Record<string, string>,
): void {
  fs.mkdirSync(path.dirname(target.path), { recursive: true });

  const settings = readSettings(target.path);
  const existingEnv = settings.env;
  const nextEnv: Record<string, string> =
    isPlainObject(existingEnv)
      ? { ...(existingEnv as Record<string, string>) }
      : {};
  for (const [k, v] of Object.entries(vars)) {
    nextEnv[k] = v;
  }
  settings.env = nextEnv;

  fs.writeFileSync(target.path, JSON.stringify(settings, null, 2) + "\n");
}

/**
 * Remove `keys` from the target's top-level `env` map. Every other env
 * entry and every other top-level settings key is preserved verbatim.
 * When `env` becomes empty as a result, the `env` key is dropped entirely
 * (no `"env": {}` residue). Returns true when the file changed, false when
 * the file was absent, malformed, or carried none of the keys — so it is
 * safe to call unconditionally (idempotent). A malformed file is left
 * untouched rather than rewritten, so we never clobber user config we
 * can't parse.
 */
export function removeAppEnvVars(
  target: AppSettingsTarget,
  keys: string[],
): boolean {
  let raw: string;
  try {
    raw = fs.readFileSync(target.path, "utf8");
  } catch {
    return false; // ENOENT
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw) as unknown;
  } catch {
    return false; // malformed — do not touch
  }
  if (!isPlainObject(parsed)) return false;
  const settings: Record<string, unknown> = { ...parsed };
  const env = settings.env;
  if (!isPlainObject(env)) return false;

  const nextEnv: Record<string, unknown> = { ...env };
  let removed = false;
  for (const k of keys) {
    if (k in nextEnv) {
      delete nextEnv[k];
      removed = true;
    }
  }
  if (!removed) return false;

  if (Object.keys(nextEnv).length === 0) {
    delete settings.env;
  } else {
    settings.env = nextEnv;
  }
  fs.writeFileSync(target.path, JSON.stringify(settings, null, 2) + "\n");
  return true;
}

function readSettings(filePath: string): Record<string, unknown> {
  try {
    const raw = fs.readFileSync(filePath, "utf8");
    const parsed = JSON.parse(raw) as unknown;
    if (isPlainObject(parsed)) return { ...parsed };
    return {};
  } catch {
    // ENOENT, malformed JSON — start from an empty object so we
    // don't lose the user's file to a stray comma. A parse error
    // does silently drop other keys, which is why the read path
    // returns {} — the write path replaces the file wholesale.
    return {};
  }
}

function readEnvMap(filePath: string): Record<string, string> {
  const settings = readSettings(filePath);
  const env = settings.env;
  if (!isPlainObject(env)) return {};
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(env)) {
    if (typeof v === "string") out[k] = v;
  }
  return out;
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return v !== null && typeof v === "object" && !Array.isArray(v);
}
","/**
 * Idempotent merge of `experimental.openTelemetry: true` into
 * `~/.config/opencode/opencode.jsonc`.
 *
 * opencode's OTLP exporter is gated on the `experimental.openTelemetry`
 * config flag — without it the SDK is constructed but never exports a
 * single span, even with all the OTEL_EXPORTER_OTLP_* env vars set on
 * the child. Path B (langwatch opencode run) is dead-on-arrival without
 * this flag flipped, so the wrapper writes it on first ingestion mode
 * invocation. Idempotent: if the key is already set true, we don't
 * touch the file. If it's set false explicitly, we DON'T overwrite —
 * the user expressed intent, surface a warning at the call site.
 *
 * The flag lives in `experimental.openTelemetry` per the binary's
 * lookup path `h.experimental?.openTelemetry` — a JSON-style nested
 * key, not a flat one.
 */

import fs from "node:fs";
import os from "node:os";
import path from "node:path";

export interface OpencodeConfigFlagResult {
  /** `created` (new file), `updated` (added/changed flag), `unchanged` (already true), `disabled-by-user` (user set false). */
  action: "created" | "updated" | "unchanged" | "disabled-by-user";
  /** Absolute path of the file that was inspected / written. */
  path: string;
}

/** Default config.jsonc path under the user's home directory. */
export function defaultOpencodeConfigPath(): string {
  const xdg = process.env.XDG_CONFIG_HOME;
  const configHome = xdg && xdg.length > 0 ? xdg : path.join(os.homedir(), ".config");
  return path.join(configHome, "opencode", "opencode.jsonc");
}

/**
 * Strip the most common JSONC noise (// line + /* block comments)
 * before JSON.parse. opencode's default config is a 2-line file with
 * just a $schema field, so this stays simple — not a full JSONC parser.
 */
function stripJsoncComments(s: string): string {
  return s
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");
}

/**
 * Set `experimental.openTelemetry = true` in the opencode config.jsonc.
 * Preserves all other top-level keys. Behaviour:
 *
 * - Missing file: write a fresh JSON document with `$schema` +
 *   `experimental.openTelemetry: true`. Action: `created`.
 * - File present, flag missing: deep-merge under `experimental`,
 *   re-serialize the whole document. Action: `updated`.
 * - File present, flag === true: no write. Action: `unchanged`.
 * - File present, flag === false: bail without overwriting; caller
 *   logs a warning so the user knows Path B will silently produce no
 *   spans until they flip it. Action: `disabled-by-user`.
 *
 * JSONC comments + trailing commas in the existing file are preserved
 * approximately by stripping them for parse + re-emitting as plain
 * JSON. A user with a heavily annotated config will lose comments
 * after this runs — acceptable for an experimental flag the wrapper
 * manages.
 */
export function setOpencodeOpenTelemetryFlag(
  options: { filePath?: string } = {},
): OpencodeConfigFlagResult {
  const filePath = options.filePath ?? defaultOpencodeConfigPath();

  if (!fs.existsSync(filePath)) {
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    const content =
      JSON.stringify(
        {
          $schema: "https://opencode.ai/config.json",
          experimental: { openTelemetry: true },
        },
        null,
        2,
      ) + "\n";
    fs.writeFileSync(filePath, content, { mode: 0o600 });
    return { action: "created", path: filePath };
  }

  const raw = fs.readFileSync(filePath, "utf8");
  let parsed: Record<string, unknown>;
  try {
    parsed = JSON.parse(stripJsoncComments(raw)) as Record<string, unknown>;
  } catch {
    parsed = { $schema: "https://opencode.ai/config.json" };
  }

  const experimental =
    (parsed.experimental as Record<string, unknown> | undefined) ?? {};
  const prior = experimental.openTelemetry;
  if (prior === true) return { action: "unchanged", path: filePath };
  if (prior === false) return { action: "disabled-by-user", path: filePath };

  parsed.experimental = { ...experimental, openTelemetry: true };
  fs.writeFileSync(filePath, JSON.stringify(parsed, null, 2) + "\n", {
    mode: 0o600,
  });
  return { action: "updated", path: filePath };
}
","import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";

export type GeminiSettingsPreflightAction =
  | "oauth-selected"
  | "api-key-selected"
  | "no-settings"
  | "parse-error";

export interface GeminiSettingsPreflightResult {
  action: GeminiSettingsPreflightAction;
  warned: boolean;
}

export interface GeminiSettingsPreflightOptions {
  filePath?: string;
  writeLine?: (line: string) => void;
}

export function defaultGeminiSettingsPath(): string {
  const home = process.env.HOME ?? os.homedir();
  return path.join(home, ".gemini", "settings.json");
}

function stripJsoncComments(s: string): string {
  return s
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");
}

export function warnIfGeminiOAuthSelected(
  options: GeminiSettingsPreflightOptions = {},
): GeminiSettingsPreflightResult {
  const filePath = options.filePath ?? defaultGeminiSettingsPath();
  const writeLine =
    options.writeLine ?? ((line: string) => process.stderr.write(line + "\n"));

  if (!fs.existsSync(filePath)) {
    return { action: "no-settings", warned: false };
  }

  let raw: string;
  try {
    raw = fs.readFileSync(filePath, "utf8");
  } catch {
    return { action: "parse-error", warned: false };
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(stripJsoncComments(raw));
  } catch {
    return { action: "parse-error", warned: false };
  }

  const selectedType = readSelectedType(parsed);

  if (selectedType === "gemini-oauth") {
    writeLine(
      "warning: ~/.gemini/settings.json has security.auth.selectedType=\"gemini-oauth\". " +
        "gemini-cli 0.46 will use cached OAuth and ignore GOOGLE_API_KEY / GEMINI_API_KEY, " +
        "so this `langwatch gemini` call will bypass the gateway. " +
        "To route through langwatch: edit ~/.gemini/settings.json and set " +
        "security.auth.selectedType to \"gemini-api-key\".",
    );
    return { action: "oauth-selected", warned: true };
  }

  return { action: "api-key-selected", warned: false };
}

function readSelectedType(parsed: unknown): string | null {
  if (parsed === null || typeof parsed !== "object") return null;
  const security = (parsed as Record<string, unknown>).security;
  if (security === null || typeof security !== "object") return null;
  const auth = (security as Record<string, unknown>).auth;
  if (auth === null || typeof auth !== "object") return null;
  const selectedType = (auth as Record<string, unknown>).selectedType;
  return typeof selectedType === "string" ? selectedType : null;
}
","/**
 * Wrapper mode selection - Path A (gateway) vs Path B (ingestion).
 *
 * Decides, before each `langwatch <tool>` invocation, which routing
 * shape to apply:
 *
 *   - Path A (gateway): VK present + provider configured + user
 *     hasn't opted out -> inject the base-URL swap envs from
 *     envForTool(). Gateway captures I/O server-side; no OTel
 *     emission from the child.
 *   - Path B (ingestion): no VK (Claude Max-style subscription,
 *     user explicitly opted in) -> mint (or reuse a cached) personal
 *     ingest key (sk-lw-*) for this tool, write the [otel] activation
 *     block to ~/.codex/config.toml (codex only), return the OTel
 *     exporter env block for the child.
 *
 * The two modes are mutually exclusive per the no-double-trace
 * rule - gateway capture + OTel emission of the same call would
 * double-count both traces and cost.
 *
 * Persisted preference lives at cfg.tool_mode[tool]; an unset
 * entry resolves at runtime as "gateway if VK present else
 * ingestion" with no prompt. Future iterations can layer a
 * first-run prompt similar to shell-rc.ts on top.
 */

import {
  codexTraceEndpoint,
  writeCodexGatewayBlock,
  writeCodexOtelBlock,
} from "@/cli/utils/codex-config-toml";
import { setOpencodeOpenTelemetryFlag } from "@/cli/utils/opencode-config-flag";

import { lwTag } from "./brand";
import type { GovernanceConfig } from "./config";
import { saveConfig } from "./config";
import {
  extractLookupIdFromToken,
  GovernanceCliError,
  listIngestionKeys,
  mintIngestionKey,
} from "./cli-api";
import { warnIfGeminiOAuthSelected } from "./gemini-settings-preflight";
import { resolvePlatformToolPolicy } from "./platform-tool-policy";

export type WrapperMode = "gateway" | "ingestion";

export interface WrapperModeResult {
  mode: WrapperMode;
  /** Env additions to merge into the child process.env. */
  vars: Record<string, string>;
  /**
   * Path of the codex config.toml that was created / updated. Set
   * for both codex Path A (writes [model_providers.langwatch]) and
   * Path B (writes [otel]).
   */
  codexConfigPath?: string;
  /**
   * Path of the sibling profile file
   * (~/.codex/langwatch-gateway.config.toml). Set only on codex
   * Path A. codex 0.134+ requires the profile body in a separate
   * file when --profile is passed.
   */
  codexProfilePath?: string;
  /**
   * Extra args to prepend to the child invocation. Used for codex
   * Path A: `--profile langwatch-gateway` forces the new provider
   * entry without touching the user's default model_provider.
   */
  extraArgs?: string[];
  /**
   * Env-var names to STRIP from the inherited parent environment
   * before merging the wrapper's vars in. Propagated from the
   * per-tool ToolEnv.clears so the resolver can pass legacy-twin
   * scrubs through to the spawn step (e.g. claude clears
   * ANTHROPIC_API_KEY so claude-code 2.x doesn't warn "Both
   * ANTHROPIC_AUTH_TOKEN and ANTHROPIC_API_KEY set, auth may not
   * work as expected").
   */
  clears?: string[];
  /** True when the wrapper minted a fresh ingest key (vs reused a cached one). */
  newKeyMinted?: boolean;
  /**
   * Path B (ingestion) only: the OTLP base endpoint (`.../api/otel`) and the
   * ingest key. The wrapper uses these AFTER the child exits to POST codex's
   * recovered turn input/output (from the rollout transcript) onto codex's own
   * trace_ids, since codex never puts content on the wire itself.
   */
  endpoint?: string;
  ingestionToken?: string;
  /**
   * Optional one-line notice for the wrapper to print to stderr, set when
   * the platform policy changed the resolved path (e.g. the org admin turned
   * direct OTLP off for this tool, so the wrapper routed through the gateway
   * instead). The member sees why the path differs from the default.
   */
  notice?: string;
}

const SOURCE_TYPE_BY_TOOL: Record<string, string> = {
  claude: "claude_code",
  codex: "codex",
  gemini: "gemini",
  opencode: "opencode",
};

/**
 * Resolve mode for a single tool invocation. Returns the env block
 * the wrapper should hand to the child process. May persist a
 * refreshed ingestion token cache to ~/.langwatch/config.json as a
 * side effect.
 *
 * Does NOT prompt the user. The path-selection UX (interactive select
 * when both paths are allowed) lives upstream in `resolveWrapperPath`,
 * which passes its decision in via `forcedMode`. When `forcedMode` is
 * omitted the resolver falls back to the legacy state-only derivation
 * (persisted tool_mode, else VK-present-implies-gateway).
 *
 * The platform policy still GATES the resolved mode here (downgrade /
 * throw) regardless of how the mode was chosen, so a forced mode the
 * org admin disabled is handled the same as before.
 */
export async function resolveWrapperMode(
  cfg: GovernanceConfig,
  tool: string,
  gatewayVars: Record<string, string>,
  gatewayClears: string[] = [],
  forcedMode?: WrapperMode,
): Promise<WrapperModeResult> {
  const persistedMode = cfg.tool_mode?.[tool];
  const hasVk = !!cfg.default_personal_vk?.secret;
  // Prefer the per-(org, tool) policy the CLI cached at login
  // (cfg.tool_policies, from the control plane's PlatformToolPolicyService).
  // An offline / legacy CLI with no cached map falls back to the hardcoded
  // defaults inside the resolver.
  const policy = resolvePlatformToolPolicy(tool, cfg.tool_policies);

  if (!policy.allowVk && !policy.allowOtelDirect) {
    throw new GovernanceCliError(
      403,
      "tool_disabled",
      `Tool '${tool}' is disabled in the platform policy (both gateway and direct OTLP paths off). Ask your org admin to enable allow_vk or allow_otel_direct.`,
    );
  }

  let notice: string | undefined;

  // EFFECTIVE mode rules:
  //   forcedMode set        -> use it (the path-selection UX upstream
  //                            already applied flag / pref / prompt /
  //                            single-allowed-path; we just honor it).
  //   persisted="gateway"   -> gateway (even if VK absent; preflight surfaces the gap)
  //   persisted="ingestion" -> ingestion
  //   persisted="ask" / unset:
  //     hasVk -> gateway (no surprise: VK users keep current behavior)
  //     no VK -> ingestion (auto-install Path B; closes the "$5 VPS" scenario)
  //
  // Platform policy then GATES the resolved mode (the both-disabled case
  // already threw above, so exactly one path is available when a swap is
  // needed):
  //   - mode=gateway + !allowVk          -> downgrade to ingestion
  //   - mode=ingestion + !allowOtelDirect -> route through the gateway
  //     (never minting an ingestion key the admin disabled)
  let mode: WrapperMode =
    forcedMode ??
    (persistedMode === "gateway"
      ? "gateway"
      : persistedMode === "ingestion"
        ? "ingestion"
        : hasVk
          ? "gateway"
          : "ingestion");

  // Symmetric fall-back: when the resolved mode is disabled but the
  // OTHER mode is allowed, swap into it rather than throwing. Lets
  // cursor (allowVk=true, allowOtelDirect=false) keep working via
  // gateway when no VK is yet configured (preflight surfaces the
  // missing VK separately, same as before this gate existed).
  //
  // The direct-OTLP gate sits ABOVE the ingestion-key mint below: when
  // the admin disabled direct OTLP for this tool, the wrapper never
  // reaches mintIngestionKey; it routes through the gateway (allowVk is
  // guaranteed true here, since the both-disabled case threw above).
  if (mode === "gateway" && !policy.allowVk) {
    mode = "ingestion";
    notice = `${lwTag()} gateway path is disabled for ${tool} by your org admin; using direct OTLP ingestion instead.`;
  }
  if (mode === "ingestion" && !policy.allowOtelDirect) {
    mode = "gateway";
    notice = `${lwTag()} direct OTLP ingestion is disabled for ${tool} by your org admin; routing through the gateway instead.`;
  }

  if (mode === "gateway") {
    if (tool === "gemini") {
      warnIfGeminiOAuthSelected();
    }
    // Codex 0.130+ defers to ChatGPT OAuth by default and ignores
    // OPENAI_API_KEY unless the active model_provider is an
    // explicit env-keyed entry. Write a langwatch provider +
    // profile to ~/.codex/config.toml and force codex into it via
    // `--profile`. Other tools (claude/gemini/cursor/opencode)
    // honour their base-URL+API-key env directly, no toml needed.
    if (tool === "codex") {
      const gw = writeCodexGatewayBlock({
        gatewayUrl: cfg.gateway_url,
        envKey: "OPENAI_API_KEY",
      });
      return {
        mode,
        vars: gatewayVars,
        clears: gatewayClears,
        codexConfigPath: gw.path,
        codexProfilePath: gw.profilePath,
        extraArgs: ["--profile", gw.profile],
        notice,
      };
    }
    return { mode, vars: gatewayVars, clears: gatewayClears, notice };
  }

  // INGESTION mode: ensure key + (for codex) toml.
  const sourceType = SOURCE_TYPE_BY_TOOL[tool];
  if (!sourceType) {
    // No ingestion template defined for this tool (cursor is the
    // current example - GUI app, no useful OTel). Fall through to
    // gateway shape; the existing preflight will tell the user
    // what's missing.
    return { mode: "gateway", vars: gatewayVars, clears: gatewayClears, notice };
  }

  // Defense-in-depth: the direct-OTLP gate above already routes to the
  // gateway when allowOtelDirect is off, so this mint is unreachable in
  // that case. Guard it explicitly so a future refactor of the gate can
  // never silently mint an ingestion key the admin disabled.
  if (!policy.allowOtelDirect) {
    throw new GovernanceCliError(
      403,
      "otel_direct_disabled",
      `Direct OTLP ingestion is disabled for '${tool}' by your org admin. Ask them to enable allow_otel_direct, or run with the gateway path.`,
    );
  }

  // Reuse a cached personal ingest key (sk-lw-*) for this source when
  // present; otherwise mint a fresh one. The mint route returns the
  // plaintext key once, so we persist it to the per-tool cache below
  // and read it back on subsequent invocations rather than re-minting.
  //
  // Stale-cache check (#4755): before reusing a cached key, confirm it is
  // still live on the platform. Token format: `ik-lw-{16-char lookupId}_{secret}`.
  // If the server resolves and the lookupId is absent → the key was revoked
  // (hard-cut rotation also invalidates the cache) → mint fresh and overwrite.
  // If the request rejects (offline / older server without this endpoint) →
  // offline-first fallback: reuse the cache so air-gapped / degraded environments
  // still work.
  const cached = cfg.default_personal_ingest_keys?.[sourceType];
  let token: string;
  let prefix: string | undefined;
  let endpoint: string;
  let minted: boolean;
  if (cached?.secret) {
    const cachedLookupId = extractLookupIdFromToken(cached.secret);
    let cacheIsLive = true; // assume live; falsified when server confirms otherwise
    try {
      const liveKeys = await listIngestionKeys(cfg);
      // Server resolved — verify the cached lookupId is still present for this sourceType
      const liveEntry = liveKeys.find(
        (k) => k.sourceType === sourceType && k.lookupId === cachedLookupId,
      );
      if (!liveEntry) {
        // Key was revoked or rotated on the platform — treat as no cache
        cacheIsLive = false;
      }
    } catch {
      // Network error / older server without the endpoint: reuse cache as-is
      // (offline-first fallback — hard-cut rotation is a re-mint-kills-old
      // invariant, so a genuinely revoked key will self-correct next time the
      // device is online).
    }
    if (cacheIsLive) {
      token = cached.secret;
      prefix = cached.prefix;
      endpoint = `${cfg.control_plane_url.replace(/\/+$/, "")}/api/otel`;
      minted = false;
    } else {
      const r = await mintIngestionKey(cfg, sourceType);
      token = r.token;
      prefix = r.prefix;
      endpoint = r.endpoint;
      minted = true;
    }
  } else {
    const r = await mintIngestionKey(cfg, sourceType);
    token = r.token;
    prefix = r.prefix;
    endpoint = r.endpoint;
    minted = true;
  }

  const vars = buildOtelEnvBlock(tool, endpoint, token);

  let codexConfigPath: string | undefined;
  if (tool === "codex") {
    // codex's OTLP/HTTP exporter sends every signal to the configured
    // endpoint verbatim - it does NOT append `/v1/traces` the way the
    // OTel SDKs in Node/Python/Go do. Spell the trace-signal suffix
    // out here so the POST lands on the real handler. codex only
    // emits traces today (no logs/metrics), so one suffix suffices.
    const result = writeCodexOtelBlock({
      endpoint: codexTraceEndpoint(endpoint),
      ingestionToken: token,
      environment: cfg.organization?.slug ?? "langwatch",
    });
    codexConfigPath = result.path;
  }

  if (tool === "opencode") {
    // opencode constructs its OTLP exporter but only EMITS spans when
    // `experimental.openTelemetry` is true in ~/.config/opencode/opencode.jsonc.
    // Without this the OTEL_EXPORTER_OTLP_* env vars we set below are
    // accepted-and-ignored - Path B silently produces nothing. Idempotent
    // merge: if the user already turned it on, no write; if they
    // explicitly set false, we don't overwrite their intent.
    setOpencodeOpenTelemetryFlag();
  }

  // Persist mode + (when freshly minted) the ingest key so the next
  // invocation skips re-deriving the mode and reuses the cached key
  // instead of minting again.
  const next: GovernanceConfig = {
    ...cfg,
    tool_mode: { ...(cfg.tool_mode ?? {}), [tool]: "ingestion" },
  };
  if (minted) {
    next.default_personal_ingest_keys = {
      ...(cfg.default_personal_ingest_keys ?? {}),
      [sourceType]: { secret: token, prefix },
    };
  }
  try {
    saveConfig(next);
  } catch {
    // Best-effort cache - failure to persist doesn't block this run.
  }

  return {
    mode,
    vars,
    codexConfigPath,
    newKeyMinted: minted,
    notice,
    endpoint,
    ingestionToken: token,
  };
}

/**
 * The env var names langwatch persists for `tool`'s Path B telemetry.
 * Derived from the same builder that installs them, so the logout /
 * removal path can strip exactly the keys the install path wrote (no
 * drift). Values are irrelevant here, so placeholders are passed in.
 */
export function telemetryEnvVarNames(tool: string): string[] {
  return Object.keys(buildOtelEnvBlock(tool, "", ""));
}

function buildOtelEnvBlock(
  tool: string,
  endpoint: string,
  token: string,
): Record<string, string> {
  const base = {
    OTEL_EXPORTER_OTLP_ENDPOINT: endpoint,
    OTEL_EXPORTER_OTLP_HEADERS: `Authorization=Bearer ${token}`,
  };

  switch (tool) {
    case "claude":
      // Three further OTel unlock knobs found in the claude-code 2.x
      // bundled binary string sweep (alongside OTEL_LOG_USER_PROMPTS
      // which we already set), all four officially documented on
      // code.claude.com/docs/en/monitoring-usage:
      //   OTEL_LOG_TOOL_DETAILS  - lifts tool_input / tool_parameters
      //     attrs (Bash command text, Edit diffs, Read file paths,
      //     etc) onto tool_decision + tool_result events. The
      //     receiver-side previously had only `tool_input_size_bytes`
      //     and `tool_result_size_bytes` - proven across the
      //     andre-claude-tool-calls + sergey-third-eye dump set.
      //   OTEL_LOG_TOOL_CONTENT  - TRACES-ONLY + requires beta
      //     tracing. claude 2.x is LOGS-ONLY today so this is a
      //     no-op for us. Set anyway as forward-compat for when
      //     claude turns on traces. Tool I/O on the logs path
      //     actually comes from TOOL_DETAILS + RAW_API_BODIES.
      //   OTEL_LOG_RAW_API_BODIES - emits two NEW event types
      //     `api_request_body` + `api_response_body` carrying the
      //     FULL JSON of every message (system prompts + user content
      //     + assistant text + tool_use blocks). THIS IS THE ONLY
      //     surface that carries the assistant response text - every
      //     other event (api_request, user_prompt, tool_*) is
      //     metadata only. Andre's live-dogfood (proxy intercept on
      //     :4318) found "UNLOCK-KNOBS-TEST-PROOF-7777" in
      //     api_response_body.content[].text with this flag set. Also
      //     the heaviest payload class (system prompts can be 100KB+,
      //     message history grows turn-over-turn) - same fat-payload
      //     class as the CH merge memory-ceiling incident
      //     [[project_skai_ch_merge_memory_ceiling_outage]].
      //
      // Default policy: ALL FOUR knobs ON. rchaves "fix everything,
      // collect all humanly possible". Payload risk is bounded:
      // claude 2.x caps api_request_body + api_response_body at 60KB
      // INLINE per event (inline is the default; the optional
      // file:<dir> mode that writes untruncated bodies to disk is NOT
      // enabled). Alexis ships a complementary receiver-side guard
      // in the same PR as defense-in-depth on fold accumulation +
      // a Body cap in case future claude versions remove the 60KB
      // inline limit. PII / logging-opt-out controls already live on
      // the platform settings page. Note: extended-thinking content
      // is ALWAYS redacted by claude from raw bodies - we cannot
      // capture it regardless of flag state.
      return {
        CLAUDE_CODE_ENABLE_TELEMETRY: "1",
        OTEL_TRACES_EXPORTER: "otlp",
        OTEL_LOGS_EXPORTER: "otlp",
        OTEL_METRICS_EXPORTER: "otlp",
        OTEL_EXPORTER_OTLP_PROTOCOL: "http/json",
        OTEL_LOG_USER_PROMPTS: "1",
        OTEL_LOG_TOOL_DETAILS: "1",
        OTEL_LOG_TOOL_CONTENT: "1",
        OTEL_LOG_RAW_API_BODIES: "1",
        ...base,
        OTEL_RESOURCE_ATTRIBUTES: "service.name=claude-code",
      };
    case "codex":
      return {
        OTEL_TRACES_EXPORTER: "otlp",
        OTEL_EXPORTER_OTLP_PROTOCOL: "http/json",
        ...base,
        OTEL_RESOURCE_ATTRIBUTES: "service.name=codex",
      };
    case "gemini":
      // gemini-cli 0.46 telemetry resolver (packages/core/dist/src/telemetry/config.js):
      //   target ∈ {local, gcp} - NOT otlp. The JSON-schema doc string
      //   mentions otlp as an "example", but the runtime validator
      //   (parseTelemetryTargetValue) only accepts local|gcp; passing
      //   otlp throws FatalConfigError at startup.
      //   To forward spans + log records to our OTLP endpoint we use
      //   `local` (in-process exporters) + `useCollector=true` which
      //   routes through @opentelemetry/exporter-trace-otlp-http +
      //   exporter-logs-otlp-http to GEMINI_TELEMETRY_OTLP_ENDPOINT
      //   (falls back to OTEL_EXPORTER_OTLP_ENDPOINT).
      //   `traces=true` enables the detail-attribute span path so the
      //   user prompt + tool calls land as span attributes (not just
      //   token counts).
      //   `logPrompts=true` is what makes gemini-cli embed the actual
      //   user prompt text in the user_prompt event - without it the
      //   receiver-side fold has no input text to lift onto
      //   langwatch.input.value, same class as claude-code.
      return {
        GEMINI_TELEMETRY_ENABLED: "true",
        GEMINI_TELEMETRY_TARGET: "local",
        GEMINI_TELEMETRY_USE_COLLECTOR: "true",
        GEMINI_TELEMETRY_TRACES_ENABLED: "true",
        GEMINI_TELEMETRY_OTLP_PROTOCOL: "http",
        GEMINI_TELEMETRY_OTLP_ENDPOINT: endpoint,
        GEMINI_TELEMETRY_LOG_PROMPTS: "true",
        OTEL_TRACES_EXPORTER: "otlp",
        OTEL_EXPORTER_OTLP_PROTOCOL: "http/json",
        ...base,
        OTEL_RESOURCE_ATTRIBUTES: "service.name=gemini-cli",
      };
    case "opencode":
      return {
        OTEL_TRACES_EXPORTER: "otlp",
        OTEL_LOGS_EXPORTER: "otlp",
        OTEL_METRICS_EXPORTER: "otlp",
        OTEL_EXPORTER_OTLP_PROTOCOL: "http/json",
        ...base,
        OTEL_RESOURCE_ATTRIBUTES: "service.name=opencode",
      };
    default:
      return base;
  }
}
","/**
 * Emit codex turn input/output (recovered from the rollout transcript) as OTLP
 * spans on codex's own per-turn trace_ids, so they join the native token-spans
 * and the trace summary's computed input/output populate with no receiver
 * change. See codex-rollout.ts for why the transcript is the only content
 * source codex offers.
 */
import { createHash } from "node:crypto";
import { readFile, readdir, stat } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";
import { type CodexTurnIO, parseCodexRollout } from "./codex-rollout";

/** Deterministic 16-hex span id derived from the turn's trace_id. */
function ioSpanId(traceId: string): string {
  return createHash("sha256").update(`${traceId}:langwatch.io`).digest("hex").slice(0, 16);
}

function attr(key: string, value: string) {
  return { key, value: { stringValue: value } };
}

interface OtlpExportRequest {
  resourceSpans: unknown[];
}

/**
 * Build an OTLP/JSON ExportTraceServiceRequest with one span per turn. Each
 * span rides codex's real trace_id and carries `langwatch.input` /
 * `langwatch.output` (read directly by the trace-summary IO accumulation) plus
 * `langwatch.span.type=llm` so the drawer renders it as the model response.
 *
 * `langwatch.input` is the full request body as the LangWatch structured
 * `chat_messages` envelope (system prompt + accumulated conversation + tool
 * calls). The receiver's `parseJsonStringValues` step parses the JSON string
 * into the `{ type, value }` object, and the LangWatch extractor canonicalises
 * it to `gen_ai.input.messages` + `gen_ai.system_instructions`, so the drawer
 * renders the same full conversation a claude trace does.
 */
export function buildCodexIOExportRequest(
  turns: CodexTurnIO[],
  nowMs: number,
): OtlpExportRequest {
  const spans = turns.map((turn) => {
    const startMs = turn.startedAtMs ?? nowMs;
    const endMs = Math.max(startMs, nowMs);
    const attributes = [
      attr("langwatch.span.type", "llm"),
      attr(
        "langwatch.input",
        JSON.stringify({ type: "chat_messages", value: turn.inputMessages }),
      ),
      attr("langwatch.output", turn.output),
    ];
    if (turn.model) {
      attributes.push(attr("gen_ai.request.model", turn.model));
      attributes.push(attr("gen_ai.response.model", turn.model));
    }
    return {
      traceId: turn.traceId,
      spanId: ioSpanId(turn.traceId),
      name: "codex.turn.response",
      kind: 1,
      startTimeUnixNano: `${startMs}000000`,
      endTimeUnixNano: `${endMs}000000`,
      attributes,
      status: {},
    };
  });

  return {
    resourceSpans: [
      {
        resource: { attributes: [attr("service.name", "codex")] },
        scopeSpans: [
          {
            // A langwatch.* scope (NOT codex_cli_rs) so the ingestion
            // infra-span filter leaves these content spans alone.
            scope: { name: "langwatch.codex.rollout" },
            spans,
          },
        ],
      },
    ],
  };
}

/**
 * Find rollout files codex wrote at or after `sinceMs`. Codex lays them out as
 * ~/.codex/sessions/YYYY/MM/DD/rollout-<ts>-<sessionid>.jsonl; we walk the
 * date subdirs and keep files whose mtime is within the session window.
 */
export async function findRecentRollouts(
  sinceMs: number,
  sessionsRoot = join(homedir(), ".codex", "sessions"),
): Promise<string[]> {
  const out: string[] = [];
  async function walk(dir: string, depth: number): Promise<void> {
    let entries;
    try {
      entries = await readdir(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const e of entries) {
      const full = join(dir, e.name);
      if (e.isDirectory()) {
        // Year/month/day nesting is 3 deep; don't descend forever.
        if (depth < 3) await walk(full, depth + 1);
      } else if (
        e.isFile() &&
        e.name.startsWith("rollout-") &&
        e.name.endsWith(".jsonl")
      ) {
        try {
          const s = await stat(full);
          if (s.mtimeMs >= sinceMs) out.push(full);
        } catch {
          /* skip unreadable */
        }
      }
    }
  }
  await walk(sessionsRoot, 0);
  return out;
}

/** Read + parse every in-window rollout into one flat turn list. */
async function readRolloutTurns(
  sinceMs: number,
  sessionsRoot: string,
): Promise<CodexTurnIO[]> {
  const files = await findRecentRollouts(sinceMs, sessionsRoot);
  const turns: CodexTurnIO[] = [];
  for (const file of files) {
    try {
      turns.push(...parseCodexRollout(await readFile(file, "utf8")));
    } catch {
      /* skip unreadable rollout */
    }
  }
  return turns;
}

/**
 * POST a batch of turns as OTLP IO spans. Capped at 5s so a slow or unreachable
 * endpoint can't wedge the user's shell; the caller swallows failures (content
 * recovery must never break a coding session).
 */
async function postCodexTurns(args: {
  turns: CodexTurnIO[];
  nowMs: number;
  endpoint: string;
  token: string;
  fetchImpl?: typeof fetch;
}): Promise<void> {
  const { turns, nowMs, endpoint, token, fetchImpl } = args;
  const body = buildCodexIOExportRequest(turns, nowMs);
  const doFetch = fetchImpl ?? fetch;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 5_000);
  try {
    await doFetch(endpoint, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        authorization: `Bearer ${token}`,
      },
      body: JSON.stringify(body),
      signal: controller.signal,
    });
  } finally {
    clearTimeout(timeout);
  }
}

/**
 * Recover codex turn I/O from rollouts written during this session and POST it
 * as OTLP spans. Best-effort and fully swallowed: a coding session must never
 * fail because the post-hoc content harvest hit a snag. Returns the number of
 * turns emitted (0 when nothing was found).
 */
export async function harvestAndEmitCodexIO(args: {
  sinceMs: number;
  nowMs: number;
  endpoint: string;
  token: string;
  sessionsRoot?: string;
  fetchImpl?: typeof fetch;
}): Promise<number> {
  const { sinceMs, nowMs, endpoint, token, sessionsRoot, fetchImpl } = args;
  const turns = await readRolloutTurns(
    sinceMs,
    sessionsRoot ?? join(homedir(), ".codex", "sessions"),
  );
  if (turns.length === 0) return 0;
  await postCodexTurns({ turns, nowMs, endpoint, token, fetchImpl });
  return turns.length;
}

/**
 * Streaming harvester: emits each turn the moment it completes instead of
 * dumping the whole session in one POST on exit. The wrapper polls `harvest()`
 * on an interval while codex runs (plus one final sweep on exit). The rollout
 * is append-only and `parseCodexRollout` only yields turns that have a reply,
 * so an in-flight turn simply isn't in the parse yet; we additionally dedup by
 * trace_id so a turn is POSTed exactly once across ticks. Re-emitting the same
 * turn would be idempotent server-side anyway (the span id is derived from the
 * trace_id), so a failed POST is safely retried on the next tick.
 */
export function createCodexIOStreamer(args: {
  sinceMs: number;
  endpoint: string;
  token: string;
  sessionsRoot?: string;
  fetchImpl?: typeof fetch;
}): { harvest: (nowMs: number) => Promise<number> } {
  const root = args.sessionsRoot ?? join(homedir(), ".codex", "sessions");
  const emitted = new Set<string>();
  return {
    async harvest(nowMs: number): Promise<number> {
      const turns = await readRolloutTurns(args.sinceMs, root);
      const fresh = turns.filter((t) => t.traceId && !emitted.has(t.traceId));
      if (fresh.length === 0) return 0;
      await postCodexTurns({
        turns: fresh,
        nowMs,
        endpoint: args.endpoint,
        token: args.token,
        fetchImpl: args.fetchImpl,
      });
      // Mark emitted only after a successful POST so a transient failure
      // retries the same turns next tick (dedup keeps the retry idempotent).
      for (const t of fresh) emitted.add(t.traceId);
      return fresh.length;
    },
  };
}
","/**
 * Codex rollout transcript -> per-turn chat-message request body + reply.
 *
 * Codex's native OTLP spans (scope `codex_cli_rs`) carry tokens, model, and
 * timing but never the prompt, the system instructions, the tool calls, or the
 * assistant reply. Codex DOES persist the whole conversation to disk as a JSONL
 * "rollout" at `~/.codex/sessions/YYYY/MM/DD/rollout-<ts>-<sessionid>.jsonl`,
 * and crucially each turn's `task_started` event records the exact OTLP
 * `trace_id` codex used for that turn's spans. That lets the wrapper recover the
 * FULL request body codex sent to the model AFTER the session and emit it on
 * codex's own trace_id, so it joins the token-spans on the same trace with no
 * receiver-side join.
 *
 * The rollout is the running conversation state (the OpenAI Responses API
 * `input` array), append-only. We replay it into an accumulating chat history
 * and, at each turn boundary, snapshot that history as the turn's `input` (the
 * request actually sent to the model: system prompt + every prior message + the
 * current user prompt + any mid-turn tool calls/results) with the turn's final
 * assistant answer as `output`. This mirrors how the claude log-to-span fold
 * turns a `/v1/messages` body into `gen_ai.input.messages`, so a codex trace
 * renders the same full conversation a claude trace does.
 *
 * Rollout line shapes this parser relies on (codex 0.137):
 * - `{"type":"session_meta","payload":{"base_instructions":"...","cwd":"..."}}`
 * - `{"type":"turn_context","payload":{"model":"gpt-5.5"}}`
 * - `{"type":"event_msg","payload":{"type":"task_started","turn_id":"...","trace_id":"<hex32>"}}`
 * - `{"type":"response_item","payload":{"type":"message","role":"developer|user|assistant","content":[{"type":"input_text|output_text","text":"..."}]}}`
 * - `{"type":"response_item","payload":{"type":"function_call","name":"exec_command","arguments":"{...}","call_id":"..."}}`
 * - `{"type":"response_item","payload":{"type":"function_call_output","call_id":"...","output":"..."}}`
 * - `{"type":"event_msg","payload":{"type":"agent_message","message":"...","phase":"final_answer"}}`
 */

/** Per-message content cap so a single huge tool output can't dominate the span. */
const MAX_CONTENT_CHARS = 30_000;
/** Whole-input cap (well under the 256KB ingestion attribute ceiling). */
const MAX_INPUT_CHARS = 120_000;
/** Final-answer cap. */
const MAX_OUTPUT_CHARS = 30_000;

/**
 * A LangWatch chat message. Roles map to the canonical chat roles
 * (`system|user|assistant|tool`); codex's `developer` role is folded into
 * `system`. Shapes a subset of the platform `chatMessageSchema` so the
 * receiver's LangWatch extractor canonicalises it to `gen_ai.input.messages`.
 */
export interface CodexChatMessage {
  role: "system" | "user" | "assistant" | "tool";
  content?: string;
  tool_calls?: {
    id: string;
    type: "function";
    function: { name: string; arguments: string };
  }[];
  tool_call_id?: string;
}

export interface CodexTurnIO {
  /** Hex OTLP trace_id codex used for this turn's spans (the join key). */
  traceId: string;
  turnId: string | null;
  model: string | null;
  /**
   * The full request body as sent to the model for this turn: the system
   * prompt, every prior message, the current user prompt, and any mid-turn
   * tool calls/results — everything except the turn's final assistant answer.
   */
  inputMessages: CodexChatMessage[];
  /** The assistant's final reply for the turn (plain text). */
  output: string;
  /** Turn start in unix ms, for a sane span start time (best-effort). */
  startedAtMs: number | null;
}

function truncate(text: string, max: number): string {
  return text.length > max ? `${text.slice(0, max)}…[truncated]` : text;
}

function textFromContent(content: unknown): string {
  if (!Array.isArray(content)) return "";
  const parts: string[] = [];
  for (const part of content) {
    if (part && typeof part === "object") {
      const t = (part as { text?: unknown }).text;
      const ot = (part as { output_text?: unknown }).output_text;
      if (typeof t === "string") parts.push(t);
      else if (typeof ot === "string") parts.push(ot);
    }
  }
  return parts.join("").trim();
}

function outputToText(output: unknown): string {
  if (typeof output === "string") return output;
  if (output && typeof output === "object") {
    // codex wraps exec output as { output: "...", metadata: {...} } sometimes
    const inner = (output as { output?: unknown }).output;
    if (typeof inner === "string") return inner;
    try {
      return JSON.stringify(output);
    } catch {
      return "";
    }
  }
  if (typeof output === "number" || typeof output === "boolean") {
    return String(output);
  }
  return "";
}

/**
 * Bound the serialized input: cap each message's content, then drop the oldest
 * NON-system messages until the whole array is under the total cap. System
 * messages (the prompt the user actually asked to see) are always preserved.
 */
function capInputMessages(messages: CodexChatMessage[]): CodexChatMessage[] {
  const capped = messages.map((m) =>
    typeof m.content === "string" && m.content.length > MAX_CONTENT_CHARS
      ? { ...m, content: truncate(m.content, MAX_CONTENT_CHARS) }
      : m,
  );
  const serializedLength = () => JSON.stringify(capped).length;
  let i = 0;
  while (serializedLength() > MAX_INPUT_CHARS && i < capped.length) {
    if (capped[i]?.role === "system") {
      i++;
      continue;
    }
    capped.splice(i, 1);
  }
  return capped;
}

/** One parsed rollout JSONL line: a tagged envelope with an opaque payload. */
interface RolloutLine {
  type?: string;
  payload?: Record<string, unknown>;
}

/** The tool call's explicit id (`call_id`, then `id`), or null if codex omitted both. */
function explicitToolCallId(payload: Record<string, unknown>): string | null {
  if (typeof payload.call_id === "string" && payload.call_id) {
    return payload.call_id;
  }
  if (typeof payload.id === "string" && payload.id) return payload.id;
  return null;
}

/**
 * Replays a codex rollout's events into a running chat history and snapshots one
 * {@link CodexTurnIO} per turn boundary. All the cross-event state (the running
 * history, the open turn, the held assistant text, the authoritative final
 * answer, the session model) lives here so {@link parseCodexRollout} stays a
 * thin parse-and-dispatch coordinator.
 */
class CodexTurnAccumulator {
  /** Emitted turns, in rollout order. */
  private readonly turns: CodexTurnIO[] = [];
  /** Accumulating conversation across the whole rollout (claude-style). */
  private readonly history: CodexChatMessage[] = [];
  private sessionModel: string | null = null;
  private cur: {
    traceId: string;
    turnId: string | null;
    model: string | null;
    startedAtMs: number | null;
  } | null = null;
  /** Latest assistant text not yet committed to history (the final-answer candidate). */
  private pendingAssistant: string | null = null;
  /** Authoritative final answer from the agent_message(final_answer) event. */
  private agentFinal: string | null = null;
  /**
   * Synthetic ids minted for tool calls that arrived without a `call_id`, queued
   * FIFO so the matching (also id-less) function_call_output pairs to the same id
   * instead of drifting as the running history grows.
   */
  private readonly pendingToolCallIds: string[] = [];
  private autoToolCallSeq = 0;

  /** Route one parsed rollout line to the handler for its event type. */
  handle(obj: RolloutLine): void {
    const payload = obj.payload ?? {};
    switch (obj.type) {
      case "session_meta":
        return this.onSessionMeta(payload);
      case "turn_context":
        return this.onTurnContext(payload);
      case "event_msg":
        return this.onEventMsg(payload);
      case "response_item":
        return this.onResponseItem(payload);
    }
  }

  /** Close the trailing open turn and return every emitted turn. */
  finish(): CodexTurnIO[] {
    this.closeTurn();
    return this.turns;
  }

  private onSessionMeta(payload: Record<string, unknown>): void {
    const bi = payload.base_instructions;
    if (typeof bi === "string" && bi.trim()) {
      this.history.push({ role: "system", content: bi.trim() });
    }
  }

  private onTurnContext(payload: Record<string, unknown>): void {
    const m = payload.model;
    if (typeof m === "string" && m) {
      this.sessionModel = m;
      if (this.cur) this.cur.model = m;
    }
  }

  private onEventMsg(payload: Record<string, unknown>): void {
    if (payload.type === "task_started") return this.onTaskStarted(payload);
    if (payload.type === "task_complete") return this.closeTurn();
    // Everything below belongs to the open turn; ignore it outside one.
    if (!this.cur) return;
    if (payload.type === "agent_message") this.onAgentMessage(payload);
  }

  private onTaskStarted(payload: Record<string, unknown>): void {
    this.closeTurn();
    const traceId =
      typeof payload.trace_id === "string" ? payload.trace_id : null;
    if (!traceId) return;
    this.cur = {
      traceId,
      turnId: typeof payload.turn_id === "string" ? payload.turn_id : null,
      model: this.sessionModel,
      startedAtMs:
        typeof payload.started_at === "number"
          ? payload.started_at * 1000
          : null,
    };
  }

  private onAgentMessage(payload: Record<string, unknown>): void {
    // The clean final answer rides the agent_message(final_answer) event; prefer
    // it over the raw assistant response_item which can repeat tool scaffolding.
    const msg = payload.message;
    if (
      typeof msg === "string" &&
      msg.trim() &&
      payload.phase === "final_answer"
    ) {
      this.agentFinal = msg.trim();
    }
  }

  private onResponseItem(payload: Record<string, unknown>): void {
    // response_items belong to the open turn; ignore them outside one.
    if (!this.cur) return;
    switch (payload.type) {
      case "message":
        return this.onMessage(payload);
      case "function_call":
        return this.onFunctionCall(payload);
      case "function_call_output":
        return this.onFunctionCallOutput(payload);
    }
  }

  private onMessage(payload: Record<string, unknown>): void {
    const role = payload.role;
    const text = textFromContent(payload.content);
    if (!text) return;
    if (role === "developer") {
      this.flushPendingAssistant();
      this.history.push({ role: "system", content: text });
    } else if (role === "user") {
      this.flushPendingAssistant();
      this.history.push({ role: "user", content: text });
    } else if (role === "assistant") {
      // Hold: this may be a mid-turn preamble (committed to history when the
      // next item arrives) or the turn's final answer (consumed by closeTurn).
      this.flushPendingAssistant();
      this.pendingAssistant = text;
    }
  }

  private onFunctionCall(payload: Record<string, unknown>): void {
    this.flushPendingAssistant();
    let callId = explicitToolCallId(payload);
    if (!callId) {
      // codex omitted the id: mint a stable one and queue it for the output.
      callId = `call_auto_${this.autoToolCallSeq++}`;
      this.pendingToolCallIds.push(callId);
    }
    const name = typeof payload.name === "string" ? payload.name : "tool";
    const args =
      typeof payload.arguments === "string"
        ? payload.arguments
        : payload.arguments != null
