  type ChatMessage,
} from "../../internal/generated/types/tracer";
import { type Prompt } from "@/client-sdk/services/prompts";
import { type AddEvaluationParams } from "../evaluation";


/**
 * Simple chat message type with just role and content
 */
export interface SimpleChatMessage {
  role: string;
  content: unknown;
}

/**
 * Valid input/output types for span data
 */
export const INPUT_OUTPUT_TYPES = [
  "text",
  "raw",
  "chat_messages",
  "list",
  "json",
  "guardrail_result",
  "evaluation_result"
] as const;

export type InputOutputType = typeof INPUT_OUTPUT_TYPES[number];


export type JsonSerializable =
  | string
  | number
  | boolean
  | null
  | JsonSerializable[]
  | Record<string, any>;

// Import attributes types from parent
import type { SemConvAttributes } from "../semconv";

/**
 * Supported types of spans for LangWatch observability. These types categorize the nature of the span for downstream analysis and visualization.
 *
 * @example
 * import { spanTypes, SpanType } from './span';
 * const myType: SpanType = 'llm';
 */
export const spanTypes = [
  "span",
  "llm",
  "chain",
  "tool",
  "agent",
  "guardrail",
  "evaluation",
  "rag",
  "prompt",
  "workflow",
  "component",
  "module",
  "server",
  "client",
  "producer",
  "consumer",
  "task",
  "unknown",
] as const;

export type SpanType = (typeof spanTypes)[number];

/**
 * Context for a RAG (Retrieval-Augmented Generation) span.
 *
 * This structure is used to record which document and chunk were retrieved and used as context for a generation.
 *
 * @property document_id - Unique identifier for the source document.
 * @property chunk_id - Unique identifier for the chunk within the document.
 * @property content - The actual content of the chunk provided to the model.
 *
 * @example
 * const ragContext: LangWatchSpanRAGContext = {
 *   document_id: 'doc-123',
 *   chunk_id: 'chunk-456',
 *   content: 'Relevant passage from the document.'
 * };
 */
export interface LangWatchSpanRAGContext {
  document_id: string;
  chunk_id: string;
  content: string;
}

/**
 * Metrics for a LangWatch span.
 *
 * @property promptTokens - The number of prompt tokens used.
 * @property completionTokens - The number of completion tokens used.
 * @property cost - The cost of the span.
 */
export interface LangWatchSpanMetrics {
  /** The number of prompt tokens used */
  promptTokens?: number;
  /** The number of completion tokens used */
  completionTokens?: number;
  /** The cost of the span */
  cost?: number;
}

/**
 * Options for creating a LangWatch span.
 *
 * @param attributes - Additional attributes to add to the span.
 */
export interface LangWatchSpanOptions extends SpanOptions {
  /** Additional attributes to add to the span. */
  attributes?: SemConvAttributes;
}

/**
 * Extension of OpenTelemetry's Span with LangWatch-specific helpers for LLM, RAG, and GenAI tracing.
 *
 * This interface provides ergonomic methods for recording structured LLM/GenAI data, such as inputs, outputs, RAG contexts, and message events.
 *
 * All methods return `this` for chaining.
 *
 * @example
 * const span = createLangWatchSpan(otelSpan);
 * span
 *   .setType('llm')
 *   .setInput({ prompt: 'Hello' })
 *   .setOutput('Hi!')
 *   .addGenAIUserMessageEvent({ content: 'Hello' })
 *   .addGenAIAssistantMessageEvent({ content: 'Hi!' });
 */
export interface LangWatchSpan extends Span {
  /**
   * Record a manual evaluation result on this span.
   *
   * This emits a `langwatch.evaluation.custom` OpenTelemetry span event whose
   * `json_encoded_event` attribute carries the evaluation payload. It matches
   * the Python SDK's `span.add_evaluation(...)` exactly, so the LangWatch
   * backend parses both identically.
   *
   * @param params - The evaluation parameters. Only `name` is required; see
   *   {@link AddEvaluationParams}. `status` defaults to `"processed"`.
   * @returns this
   *
   * @example
   * ```typescript
   * span.addEvaluation({
   *   name: "response_quality",
   *   passed: true,
   *   score: 0.95,
   *   details: "High quality response",
   * });
   * ```
   */
  addEvaluation(params: AddEvaluationParams): this;

  /**
   * @deprecated Use {@link LangWatchSpan.addEvaluation} instead. Alias kept for
   * backward compatibility with earlier documentation.
   *
   * @param params - The evaluation parameters. See {@link AddEvaluationParams}.
   * @returns this
   */
  recordEvaluation(params: AddEvaluationParams): this;

  /**
   * Set multiple attributes for the span.
   *
   * @param attributes - The attributes object
   * @returns this
   */
  setAttributes(attributes: SemConvAttributes): this;

  /**
   * Set a single attribute for the span.
   *
   * @param key - The attribute key
   * @param value - The attribute value
   * @returns this
   */
  setAttribute(key: keyof SemConvAttributes, value: AttributeValue): this;

  /**
   * Set the type of the span (e.g., 'llm', 'rag', 'tool', etc).
   *
   * This is used for downstream filtering and analytics.
   *
   * @param type - The span type (see SpanType)
   * @returns this
   */
  setType(type: SpanType): this;

  /**
   * Set the request model name for the span.
   *
   * This is typically the model name sent in the API request (e.g., 'gpt-4', 'claude-3').
   *
   * @param model - The request model name
   * @returns this
   */
  setRequestModel(model: string): this;
  /**
   * Set the response model name for the span.
   *
   * This is the model name returned in the API response, if different from the request.
   *
   * @param model - The response model name
   * @returns this
   */
  setResponseModel(model: string): this;

  /**
   * Set multiple RAG contexts for the span.
   *
   * Use this to record all retrieved documents/chunks used as context for a generation.
   *
   * @param ragContexts - Array of RAG context objects
   * @returns this
   */
  setRAGContexts(ragContexts: LangWatchSpanRAGContext[]): this;
  /**
   * Set a single RAG context for the span.
   *
   * Use this if only one context was retrieved.
   *
   * @param ragContext - The RAG context object
   * @returns this
   */
  setRAGContext(ragContext: LangWatchSpanRAGContext): this;

  /**
   * Set the metrics for the span.
   *
   * @param metrics - The metrics object
   * @returns this
   */
  setMetrics(metrics: LangWatchSpanMetrics): this;

  /**
   * Set the selected prompt for the span. This will attach this prompt to the trace. If
   * this is set on multiple spans, the last one will be used.
   *
   * @param prompt - The prompt object
   * @returns this
   */
  setSelectedPrompt(prompt: Prompt): this;

  /**
   * Record the input to the span with explicit type control.
   *
   * @param type - Force as "text" type
   * @param input - String input value
   * @returns this
   */
  setInput(type: "text", input: string): this;
  /**
   * Record the input to the span with explicit type control.
   *
   * @param type - Force as "raw" type
   * @param input - Any input value
   * @returns this
   */
  setInput(type: "raw", input: unknown): this;
  /**
   * Record the input to the span with explicit type control.
   *
   * @param type - Force as "chat_messages" type
   * @param input - Chat messages array (supports both ChatMessage[] and SimpleChatMessage[])
   * @returns this
   */
  setInput(type: "chat_messages", input: ChatMessage[] | SimpleChatMessage[]): this;
  /**
   * Record the input to the span with explicit type control.
   *
   * @param type - Force as "list" type
   * @param input - SpanInputOutput array
   * @returns this
   */
  setInput(type: "list", input: SpanInputOutput[]): this;
  /**
   * Record the input to the span with explicit type control.
   *
   * @param type - Force as "json" type
   * @param input - Any JSON-serializable value
   * @returns this
   */
  setInput(type: "json", input: unknown): this;
  /**
   * Record the input to the span with explicit type control.
   *
   * @param type - Force as "guardrail_result" type
   * @param input - Guardrail result value
   * @returns this
   */
  setInput(type: "guardrail_result", input: unknown): this;
  /**
   * Record the input to the span with explicit type control.
   *
   * @param type - Force as "evaluation_result" type
   * @param input - Evaluation result value
   * @returns this
   */
  setInput(type: "evaluation_result", input: unknown): this;
  /**
   * Record the input to the span with automatic type detection.
   *
   * Automatically detects: strings → text, ChatMessage[] → chat_messages,
   * arrays → list, objects → json.
   *
   * @param input - The input value (auto-detected type)
   * @returns this
   */
  setInput(input: unknown): this;

  /**
   * Record the output from the span with explicit type control.
   *
   * @param type - Force as "text" type
   * @param output - String output value
   * @returns this
   */
  setOutput(type: "text", output: string): this;
  /**
   * Record the output from the span with explicit type control.
   *
   * @param type - Force as "raw" type
   * @param output - Any output value
   * @returns this
   */
  setOutput(type: "raw", output: unknown): this;
  /**
   * Record the output from the span with explicit type control.
   *
   * @param type - Force as "chat_messages" type
   * @param output - Chat messages array (supports both ChatMessage[] and SimpleChatMessage[])
   * @returns this
   */
  setOutput(type: "chat_messages", output: ChatMessage[] | SimpleChatMessage[]): this;
  /**
   * Record the output from the span with explicit type control.
   *
   * @param type - Force as "list" type
   * @param output - SpanInputOutput array
   * @returns this
   */
  setOutput(type: "list", output: SpanInputOutput[]): this;
  /**
   * Record the output from the span with explicit type control.
   *
   * @param type - Force as "json" type
   * @param output - Any JSON-serializable value
   * @returns this
   */
  setOutput(type: "json", output: unknown): this;
  /**
   * Record the output from the span with explicit type control.
   *
   * @param type - Force as "guardrail_result" type
   * @param output - Guardrail result value
   * @returns this
   */
  setOutput(type: "guardrail_result", output: unknown): this;
  /**
   * Record the output from the span with explicit type control.
   *
   * @param type - Force as "evaluation_result" type
   * @param output - Evaluation result value
   * @returns this
   */
  setOutput(type: "evaluation_result", output: unknown): this;
  /**
   * Record the output from the span with automatic type detection.
   *
   * Automatically detects: strings → text, ChatMessage[] → chat_messages,
   * arrays → list, objects → json.
   *
   * @param output - The output value (auto-detected type)
   * @returns this
   */
  setOutput(output: unknown): this;

  // /**
  //  * Set the evaluation output for the span.
  //  *
  //  * @param guardrail - Whether the evaluation is a guardrail
  //  * @param output - The evaluation result
  //  * @returns this
  //  */
  // setOutputEvaluation(guardrail: boolean, output: EvaluationResultModel): this;
}
","import { z } from "zod";

// ---------------------------------------------------------------------------
// Tracer schemas (Zod-first). Every shared trace/span/evaluation shape is
// defined as a Zod schema and its TypeScript type is inferred with z.infer,
// so the schema and the type can never drift apart. The few ElasticSearch and
// dataset shapes that are pure structural transforms (Omit/Partial of the
// schemas above) stay as inferred-type derivations.
// ---------------------------------------------------------------------------

const chatRoleSchema = z.union([
  z.literal("system"),
  z.literal("user"),
  z.literal("assistant"),
  z.literal("function"),
  z.literal("tool"),
  z.literal("unknown"),
]);

type ChatRole = z.infer<typeof chatRoleSchema>;

const functionCallSchema = z.object({
  name: z.string().optional(),
  arguments: z.string().optional(),
});

type FunctionCall = z.infer<typeof functionCallSchema>;

const toolCallSchema = z.object({
  id: z.string(),
  type: z.string(),
  function: functionCallSchema,
});

type ToolCall = z.infer<typeof toolCallSchema>;

export const rAGChunkSchema = z.object({
  document_id: z.string().optional().nullable(),
  chunk_id: z.string().optional().nullable(),
  content: z.union([
    z.string(),
    z.record(z.string(), z.any()),
    z.array(z.any()),
  ]),
});

export type RAGChunk = z.infer<typeof rAGChunkSchema>;

export const contextsSchema = z.object({
  traceId: z.string(),
  contexts: z.array(rAGChunkSchema),
});

export type Contexts = z.infer<typeof contextsSchema>;

export const chatRichContentSchema = z.union([
  z.object({
    type: z.literal("text"),
    text: z.string().optional(),
    /** pi-ai uses `content` instead of `text` inside text blocks */
    content: z.string().optional(),
  }),
  z.object({
    text: z.string(),
  }),
  z.object({
    type: z.literal("image_url"),
    image_url: z
      .object({
        url: z.string(),
        detail: z
          .union([z.literal("auto"), z.literal("low"), z.literal("high")])
          .optional(),
      })
      .optional(),
  }),
  z.object({
    type: z.literal("tool_call"),
    toolName: z.string().optional(),
    toolCallId: z.string().optional(),
    args: z.string().optional(),
  }),
  z.object({
    type: z.literal("tool_result"),
    toolName: z.string().optional(),
    toolCallId: z.string().optional(),
    result: z.any().optional(),
  }),
  /**
   * AG-UI binary content part. Used for audio/image/video/file attachments.
   * Mutually-exclusive payload: exactly one of `data` (inline base64), `url`
   * (already-externalized reference), or `id` (stored_objects id) is present.
   * After ingest-side extraction (stored-objects pipeline), inline `data` is
   * rewritten to `id` + `url` pointing at /api/files/{id}.
   */
  z.object({
    type: z.literal("binary"),
    mimeType: z.string(),
    data: z.string().optional(),
    url: z.string().optional(),
    id: z.string().optional(),
    filename: z.string().optional(),
  }),
  /**
   * OpenAI Realtime `input_audio` content part. Pre-extraction the payload is
   * inline base64 (`{ data, format }`); after ingest-side stored-objects
   * extraction it is rewritten to a reference (`{ url, mimeType }`) pointing at
   * /api/files/{projectId}/{id}. Every field is optional so this validates both
   * shapes. Mirrors `inputAudioContentPartSchema` in the scenario event schemas.
   */
  z.object({
    type: z.literal("input_audio"),
    input_audio: z.object({
      data: z.string().optional(),
      format: z.string().optional(),
      url: z.string().optional(),
      mimeType: z.string().optional(),
      id: z.string().optional(),
    }),
  }),
  /**
   * AG-UI media `audio` content part. A typed `source` carries either an
   * externalized `url` or inline base64 `data`, with an optional `mimeType`.
   * Shared shape with image/video/document media parts (see `visitContentPart`).
   */
  z.object({
    type: z.literal("audio"),
    source: z.object({
      type: z.union([z.literal("url"), z.literal("data")]),
      value: z.string(),
      mimeType: z.string().optional(),
    }),
  }),
]);

export type ChatRichContent = z.infer<typeof chatRichContentSchema>;

export const chatMessageSchema = z.object({
  role: chatRoleSchema.optional(),
  content: z
    .union([z.string(), z.array(chatRichContentSchema)])
    .optional()
    .nullable(),
  /** Vercel AI SDK / pi-ai use `parts` instead of `content` */
  parts: z.array(chatRichContentSchema).optional(),
  function_call: functionCallSchema.optional().nullable(),
  tool_calls: z.array(toolCallSchema).optional().nullable(),
  tool_call_id: z.string().optional().nullable(),
  name: z.string().optional().nullable(),
  reasoning_content: z.string().optional().nullable(),
});

export type ChatMessage = z.infer<typeof chatMessageSchema>;

const typedValueTextSchema = z.object({
  type: z.literal("text"),
  value: z.string(),
});

type TypedValueText = z.infer<typeof typedValueTextSchema>;

const typedValueRawSchema = z.object({
  type: z.literal("raw"),
  value: z.string(),
});

type TypedValueRaw = z.infer<typeof typedValueRawSchema>;

const jSONSerializableSchema = z
  .union([
    z.string(),
    z.number(),
    z.boolean(),
    z.record(z.string(), z.any()),
    z.array(z.any()),
  ])
  .nullable();

export const typedValueJsonSchema = z.object({
  type: z.literal("json"),
  value: jSONSerializableSchema,
});

export type TypedValueJson = z.infer<typeof typedValueJsonSchema>;

export const moneySchema = z.object({
  currency: z.string(),
  amount: z.number(),
});

export type Money = z.infer<typeof moneySchema>;

export const evaluationResultSchema = z.object({
  status: z.union([
    z.literal("processed"),
    z.literal("skipped"),
    z.literal("error"),
  ]),
  passed: z.boolean().optional().nullable(),
  score: z.number().optional().nullable(),
  label: z.string().optional().nullable(),
  details: z.string().optional().nullable(),
  cost: moneySchema.optional().nullable(),
});

export type EvaluationResult = z.infer<typeof evaluationResultSchema>;

export const typedValueGuardrailResultSchema = z.object({
  type: z.literal("guardrail_result"),
  value: evaluationResultSchema,
});

export type TypedValueGuardrailResult = z.infer<
  typeof typedValueGuardrailResultSchema
>;

export const typedValueEvaluationResultSchema = z.object({
  type: z.literal("evaluation_result"),
  value: evaluationResultSchema,
});

export type TypedValueEvaluationResult = z.infer<
  typeof typedValueEvaluationResultSchema
>;

export const typedValueChatMessagesSchema = z.object({
  type: z.literal("chat_messages"),
  value: z.array(chatMessageSchema),
});

export type TypedValueChatMessages = z.infer<
  typeof typedValueChatMessagesSchema
>;

export type SpanInputOutput =
  | TypedValueText
  | TypedValueChatMessages
  | TypedValueGuardrailResult
  | TypedValueEvaluationResult
  | TypedValueJson
  | TypedValueRaw
  | {
      type: "list";
      value: SpanInputOutput[];
    };

export const spanInputOutputSchema: z.ZodType<SpanInputOutput> = z.lazy(() =>
  z.union([
    typedValueTextSchema,
    typedValueChatMessagesSchema,
    typedValueGuardrailResultSchema,
    typedValueEvaluationResultSchema,
    typedValueJsonSchema,
    typedValueRawSchema,
    z.object({
      type: z.literal("list"),
      value: z.array(spanInputOutputSchema),
    }),
  ]),
);

export const errorCaptureSchema = z.object({
  has_error: z.literal(true),
  message: z.string(),
  stacktrace: z.array(z.string()),
});

export type ErrorCapture = z.infer<typeof errorCaptureSchema>;

export const spanMetricsSchema = z.object({
  prompt_tokens: z.number().optional().nullable(),
  completion_tokens: z.number().optional().nullable(),
  reasoning_tokens: z.number().optional().nullable(),
  cache_read_input_tokens: z.number().optional().nullable(),
  cache_creation_input_tokens: z.number().optional().nullable(),
  tokens_estimated: z.boolean().optional().nullable(),
  cost: z.number().optional().nullable(),
});

export type SpanMetrics = z.infer<typeof spanMetricsSchema>;

export const reservedSpanParamsSchema = z.object({
  frequency_penalty: z.number().optional().nullable(),
  logit_bias: z.record(z.string(), z.number()).optional().nullable(),
  logprobs: z.boolean().optional().nullable(),
  top_logprobs: z.number().optional().nullable(),
  max_tokens: z.number().optional().nullable(),
  n: z.number().optional().nullable(),
  presence_penalty: z.number().optional().nullable(),
  seed: z.number().optional().nullable(),
  stop: z
    .union([z.string(), z.array(z.string())])
    .optional()
    .nullable(),
  stream: z.boolean().optional().nullable(),
  temperature: z.number().optional().nullable(),
  top_p: z.number().optional().nullable(),
  tools: z.array(z.record(z.string(), z.any())).optional().nullable(),
  tool_choice: z
    .union([z.record(z.string(), z.any()), z.string()])
    .optional()
    .nullable(),
  parallel_tool_calls: z.boolean().optional().nullable(),
  functions: z.array(z.record(z.string(), z.any())).optional().nullable(),
  user: z.string().optional().nullable(),
  reasoning_effort: z.string().optional().nullable(),
});

export type ReservedSpanParams = z.infer<typeof reservedSpanParamsSchema>;

export const spanParamsSchema = reservedSpanParamsSchema.and(
  z.record(z.string(), z.any()),
);

export type SpanParams = z.infer<typeof spanParamsSchema>;

export const spanTimestampsSchema = z.object({
  ignore_timestamps_on_write: z.boolean().optional().nullable(),
  started_at: z.number(),
  first_token_at: z.number().optional().nullable(),
  finished_at: z.number(),
});

export type SpanTimestamps = z.infer<typeof spanTimestampsSchema>;

export const spanTypesSchema = z.union([
  z.literal("span"),
  z.literal("llm"),
  z.literal("chain"),
  z.literal("tool"),
  z.literal("agent"),
  z.literal("rag"),
  z.literal("guardrail"),
  z.literal("evaluation"),
  // Low-code
  z.literal("workflow"),
  z.literal("component"),
  // DSPy
  z.literal("module"),
  // OpenTelemetry
  z.literal("server"),
  z.literal("client"),
  z.literal("producer"),
  z.literal("consumer"),
  // Other
  z.literal("task"), // openllmetry
  z.literal("unknown"),
]);

export type SpanTypes = z.infer<typeof spanTypesSchema>;

export const baseSpanSchema = z.object({
  span_id: z.string(),
  parent_id: z.string().optional().nullable(),
  trace_id: z.string(),
  type: spanTypesSchema,
  name: z.string().optional().nullable(),
  input: spanInputOutputSchema.optional().nullable(),
  output: spanInputOutputSchema.optional().nullable(),
  error: errorCaptureSchema.optional().nullable(),
  timestamps: spanTimestampsSchema,
  metrics: spanMetricsSchema.optional().nullable(),
  params: spanParamsSchema.optional().nullable(),
});

export type BaseSpan = z.infer<typeof baseSpanSchema>;

export const lLMSpanSchema = baseSpanSchema.extend({
  type: z.literal("llm"),
  // TODO: deprecate field, standardize on litellm model names
  vendor: z.string().optional().nullable(),
  model: z.string().optional().nullable(),
});

export type LLMSpan = z.infer<typeof lLMSpanSchema>;

export const rAGSpanSchema = baseSpanSchema.extend({
  type: z.literal("rag"),
  contexts: z.array(rAGChunkSchema),
});

export type RAGSpan = z.infer<typeof rAGSpanSchema>;

export const spanSchema = z.union([
  lLMSpanSchema,
  rAGSpanSchema,
  baseSpanSchema,
]);

export type Span = z.infer<typeof spanSchema>;

const spanInputOutputValidatorSchema = spanInputOutputSchema.and(
  z.object({
    value: z.any(),
  }),
);

export const spanValidatorSchema = z
  .union([
    lLMSpanSchema.omit({ input: true, output: true, params: true }),
    rAGSpanSchema.omit({ input: true, output: true, params: true }),
    baseSpanSchema.omit({ input: true, output: true, params: true }),
  ])
  .and(
    z.object({
      input: spanInputOutputValidatorSchema.optional().nullable(),
      output: spanInputOutputValidatorSchema.optional().nullable(),
      params: z.record(z.string(), z.any()).optional().nullable(),
    }),
  );

export type SpanValidator = z.infer<typeof spanValidatorSchema>;

export type ElasticSearchInputOutput = {
  type: SpanInputOutput["type"];
  value: string;
};

// Dead ElasticSearch shape kept as a structural type only (no schema needed).
export type ElasticSearchSpan = Omit<
  BaseSpan & Partial<Omit<RAGSpan, "type">> & Partial<Omit<LLMSpan, "type">>,
  "input" | "output"
> & {
  project_id: string;
  input?: ElasticSearchInputOutput | null;
  output?: ElasticSearchInputOutput | null;
  timestamps: SpanTimestamps & { inserted_at: number; updated_at: number };
};

export const traceInputSchema = z.object({
  value: z.string(),
});

export type TraceInput = z.infer<typeof traceInputSchema>;

export const traceOutputSchema = z.object({
  value: z.string(),
});

export type TraceOutput = z.infer<typeof traceOutputSchema>;

const primitiveTypeSchema = z
  .union([z.string(), z.number(), z.boolean(), z.undefined()])
  .nullable();

export const reservedTraceMetadataSchema = z.object({
  thread_id: z.string().optional().nullable(),
  user_id: z.string().optional().nullable(),
  customer_id: z.string().optional().nullable(),
  labels: z.array(z.string()).optional().nullable(),
  topic_id: z.string().optional().nullable(),
  subtopic_id: z.string().optional().nullable(),
  sdk_name: z.string().optional().nullable(),
  sdk_version: z.string().optional().nullable(),
  sdk_language: z.string().optional().nullable(),
  telemetry_sdk_language: z.string().optional().nullable(),
  telemetry_sdk_name: z.string().optional().nullable(),
  telemetry_sdk_version: z.string().optional().nullable(),
  prompt_ids: z.array(z.string()).optional().nullable(),
  prompt_version_ids: z.array(z.string()).optional().nullable(),
});

export type ReservedTraceMetadata = z.infer<typeof reservedTraceMetadataSchema>;

export const reservedTraceMetadataMappingSchema = z.record(
  z.string(),
  reservedTraceMetadataSchema.keyof(),
);

export type ReservedTraceMetadataMapping = z.infer<
  typeof reservedTraceMetadataMappingSchema
>;

export const customMetadataSchema = z.record(
  z.string(),
  z.union([
    primitiveTypeSchema,
    z.array(primitiveTypeSchema),
    z.record(z.string(), primitiveTypeSchema),
    z.record(z.string(), z.record(z.string(), primitiveTypeSchema)),
  ]),
);

export type CustomMetadata = z.infer<typeof customMetadataSchema>;

export const traceMetadataSchema =
  reservedTraceMetadataSchema.and(customMetadataSchema);

export type TraceMetadata = z.infer<typeof traceMetadataSchema>;

export const eventSchema = z.object({
  event_id: z.string(),
  event_type: z.string(), // Type of event (e.g., 'thumbs_up_down', 'add_to_cart')
  project_id: z.string(),
  metrics: z.record(z.string(), z.number()),
  event_details: z.record(z.string(), z.string()),
  trace_id: z.string(),
  timestamps: z.object({
    started_at: z.number(),
    inserted_at: z.number(),
    updated_at: z.number(),
  }),
});

export type Event = z.infer<typeof eventSchema>;

export const elasticSearchEventSchema = eventSchema
  .omit({ metrics: true, event_details: true })
  .and(
    z.object({
      metrics: z.array(
        z.object({
          key: z.string(),
          value: z.number(),
        }),
      ),
      event_details: z.array(
        z.object({
          key: z.string(),
          value: z.string(),
        }),
      ),
    }),
  );

export type ElasticSearchEvent = z.infer<typeof elasticSearchEventSchema>;

const evaluationStatusSchema = z.union([
  z.literal("scheduled"),
  z.literal("in_progress"),
  z.literal("error"),
  z.literal("skipped"),
  z.literal("processed"),
]);

export const evaluationSchema = z.object({
  evaluation_id: z.string(),
  evaluator_id: z.string(),
  span_id: z.string().optional().nullable(),
  name: z.string(),
  type: z.string().optional().nullable(),
  is_guardrail: z.boolean().optional().nullable(),
  evaluation_thread_id: z.string().optional().nullable(), // Thread ID used for thread-based evaluation data
  status: evaluationStatusSchema,
  passed: z.boolean().optional().nullable(),
  score: z.number().optional().nullable(),
  label: z.string().optional().nullable(),
  details: z.string().optional().nullable(),
  inputs: z.record(z.string(), z.any()).optional().nullable(),
  error: errorCaptureSchema.optional().nullable(),
  retries: z.number().optional().nullable(),
  timestamps: z.object({
    ignore_timestamps_on_write: z.boolean().optional().nullable(),
    inserted_at: z.number().optional().nullable(),
    started_at: z.number().optional().nullable(),
    finished_at: z.number().optional().nullable(),
    updated_at: z.number().optional().nullable(),
  }),
});

export type Evaluation = z.infer<typeof evaluationSchema>;

export const elasticSearchEvaluationSchema = evaluationSchema;

export type ElasticSearchEvaluation = z.infer<
  typeof elasticSearchEvaluationSchema
>;

export const rESTEvaluationSchema = evaluationSchema
  .omit({
    evaluation_id: true,
    evaluator_id: true,
    status: true,
    timestamps: true,
    retries: true,
  })
  .and(
    z.object({
      evaluation_id: z.string().optional().nullable(),
      evaluator_id: z.string().optional().nullable(),
      status: z
        .union([
          z.literal("processed"),
          z.literal("skipped"),
          z.literal("error"),
        ])
        .optional()
        .nullable(),
      timestamps: z
        .object({
          started_at: z.number().optional().nullable(),
          finished_at: z.number().optional().nullable(),
        })
        .optional()
        .nullable(),
    }),
  );

export type RESTEvaluation = z.infer<typeof rESTEvaluationSchema>;

export const tracePrivacySchema = z.object({
  // Content categories that a `drop` privacy policy stripped before the spans
  // were stored, derived at read time from the marker the drop stamps on each
  // span. The content was never stored and cannot be recovered, which is what
  // distinguishes it from a read-time `restrict` (the data is kept and hidden by
  // audience, surfaced through the field-redaction path). Absent when nothing
  // was dropped.
  droppedCategories: z.array(z.string()).optional(),
});

export type TracePrivacy = z.infer<typeof tracePrivacySchema>;

export const traceSchema = z.object({
  trace_id: z.string(),
  project_id: z.string(),
  metadata: traceMetadataSchema,
  privacy: tracePrivacySchema.optional(),
  timestamps: z.object({
    started_at: z.number(),
    inserted_at: z.number(),
    updated_at: z.number(),
  }),
  input: traceInputSchema.optional(),
  output: traceOutputSchema.optional(),
  contexts: z.array(rAGChunkSchema).optional(),
  expected_output: z
    .object({
      value: z.string(),
    })
    .optional(),
  metrics: z
    .object({
      first_token_ms: z.number().optional().nullable(),
      total_time_ms: z.number().optional().nullable(),
      prompt_tokens: z.number().optional().nullable(),
      completion_tokens: z.number().optional().nullable(),
      reasoning_tokens: z.number().optional().nullable(),
      cache_read_input_tokens: z.number().optional().nullable(),
      cache_creation_input_tokens: z.number().optional().nullable(),
      total_cost: z.number().optional().nullable(),
      tokens_estimated: z.boolean().optional().nullable(),
    })
    .optional(),
  error: errorCaptureSchema.optional().nullable(),
  indexing_md5s: z.array(z.string()).optional(),
  events: z.array(eventSchema).optional(),
  evaluations: z.array(evaluationSchema).optional(),
  spans: z.array(spanSchema),
  // Set server-side when content was teaser-redacted by the plan's
  // visibility window — the UI renders the upgrade CTA off this flag.
  redacted_by_visibility_window: z.boolean().optional(),
});

export type Trace = z.infer<typeof traceSchema>;

export const lLMModeTraceSchema = traceSchema
  .omit({ timestamps: true, indexing_md5s: true })
  .and(
    z.object({
      timestamps: z.object({
        started_at: z.string(),
        inserted_at: z.string(),
        updated_at: z.string(),
      }),
      ascii_tree: z.string(),
    }),
  );

export type LLMModeTrace = z.infer<typeof lLMModeTraceSchema>;

// Dead ElasticSearch shape kept as a structural type only (no schema needed).
export type ElasticSearchTrace = Omit<
  Trace,
  "metadata" | "timestamps" | "events" | "privacy"
> & {
  metadata: ReservedTraceMetadata & {
    custom?: CustomMetadata;
    all_keys?: string[];
  };
